insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f7000000-0000-0000-0000-000000000001', 'mrcp1', 'd850e569-b182-4bde-93f5-5e5c4f0fd1c3',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f7000000-0000-0000-0000-000000000001', 'A', 'Proliferative diabetic retinopathy', false, 'Ruled out because proliferative retinopathy is specifically defined by the presence of neovascularisation (new abnormal blood vessel growth), which is explicitly absent here.', 1),
('f7000000-0000-0000-0000-000000000001', 'B', 'Diabetic maculopathy', false, 'Ruled out because although exudates can be part of maculopathy if affecting the macula specifically, the description here is of general background retinopathy findings without specifically confirmed macular involvement or oedema.', 2),
('f7000000-0000-0000-0000-000000000001', 'C', 'Normal fundoscopic findings for his age', false, 'Ruled out because microaneurysms, haemorrhages and exudates are specific, abnormal findings indicating diabetic retinopathy, not normal age-related fundal appearance.', 3),
('f7000000-0000-0000-0000-000000000001', 'D', 'Background (non-proliferative) diabetic retinopathy', true, 'Correct. Microaneurysms, dot and blot haemorrhages, and hard exudates, without neovascularisation, are characteristic of background (non-proliferative) diabetic retinopathy, reflecting early microvascular damage from chronic hyperglycaemia, requiring continued monitoring and optimisation of glycaemic control.', 4),
('f7000000-0000-0000-0000-000000000001', 'E', 'Central retinal vein occlusion', false, $x$Ruled out because CRVO causes widespread retinal haemorrhages with a characteristic 'blood and thunder' appearance and optic disc swelling, a different and more acute pattern from the chronic background retinopathy changes described here.$x$, 5),
('f7000000-0000-0000-0000-000000000002', 'A', 'Observation only, as there are no visual symptoms', false, 'Ruled out because proliferative diabetic retinopathy carries a significant risk of severe visual loss if untreated, regardless of current symptoms; active treatment (laser therapy) is indicated once neovascularisation is identified, not simply observation.', 1),
('f7000000-0000-0000-0000-000000000002', 'B', 'Oral antibiotics', false, 'Ruled out because diabetic retinopathy is a vascular, not infective, process; antibiotics have no role in its treatment.', 2),
('f7000000-0000-0000-0000-000000000002', 'C', 'Immediate vitrectomy as first-line treatment', false, 'Ruled out because vitrectomy is reserved for specific complications (e.g. significant vitreous haemorrhage, tractional retinal detachment) not responding to or unsuitable for laser treatment, not as first-line management for uncomplicated proliferative retinopathy.', 3),
('f7000000-0000-0000-0000-000000000002', 'D', 'Simply improving glycaemic control alone, with no specific ocular treatment', false, 'Ruled out because although optimising glycaemic control remains important for overall diabetes management, established proliferative retinopathy requires specific ocular treatment (laser photocoagulation) to reduce the risk of severe visual loss, not glycaemic control alone.', 4),
('f7000000-0000-0000-0000-000000000002', 'E', 'Pan-retinal photocoagulation (laser therapy)', true, 'Correct. Proliferative diabetic retinopathy, characterised by retinal neovascularisation, is treated with pan-retinal photocoagulation, which reduces the retinal ischaemic drive for neovascularisation by ablating peripheral ischaemic retina, significantly reducing the risk of severe visual loss from vitreous haemorrhage or tractional retinal detachment, even in the absence of current visual symptoms.', 5),
('f7000000-0000-0000-0000-000000000003', 'A', 'Pan-retinal photocoagulation as first-line treatment', false, 'Ruled out because pan-retinal photocoagulation is the treatment for proliferative retinopathy (targeting peripheral ischaemic retina), not the first-line treatment for macular oedema, which is more specifically targeted with anti-VEGF therapy (or, in some cases, focal/grid laser or steroid implants).', 1),
('f7000000-0000-0000-0000-000000000003', 'B', 'Oral corticosteroids', false, 'Ruled out because oral corticosteroids are not standard treatment for diabetic macular oedema; targeted intravitreal treatments (anti-VEGF or, in some cases, intravitreal steroid) are used instead, delivering treatment directly to the affected tissue while minimising systemic exposure.', 2),
('f7000000-0000-0000-0000-000000000003', 'C', 'Intravitreal anti-VEGF injection therapy', true, 'Correct. Diabetic macular oedema, confirmed on OCT and causing central visual loss, is treated first-line with intravitreal anti-VEGF injections, which reduce vascular permeability and macular fluid accumulation, helping to preserve or improve central vision.', 3),
('f7000000-0000-0000-0000-000000000003', 'D', 'Observation only, as this is expected with long-standing diabetes', false, 'Ruled out because diabetic macular oedema causing visual loss requires active treatment to preserve vision, not simple observation, given the availability of effective therapy.', 4),
('f7000000-0000-0000-0000-000000000003', 'E', 'Immediate vitrectomy', false, 'Ruled out because vitrectomy is not first-line treatment for macular oedema; it is reserved for specific complications not amenable to or responding to medical/laser treatment.', 5),
('f7000000-0000-0000-0000-000000000004', 'A', 'Early worsening of retinopathy, a recognised transient phenomenon following rapid improvement in glycaemic control', true, 'Correct. Rapid, significant improvement in glycaemic control can paradoxically cause a transient early worsening of diabetic retinopathy before longer-term benefit is seen; this is a recognised phenomenon, meaning patients with pre-existing retinopathy undergoing rapid glycaemic optimisation should have close ophthalmological monitoring during this period, though the long-term benefit of good glycaemic control on retinopathy risk remains well-established.', 1),
('f7000000-0000-0000-0000-000000000004', 'B', 'This indicates her diabetes is now completely uncontrolled', false, 'Ruled out because her HbA1c has, in fact, significantly improved; the retinopathy worsening reflects a specific, recognised transient phenomenon related to the rapidity of improvement, not ongoing poor control.', 2),
('f7000000-0000-0000-0000-000000000004', 'C', 'This is unrelated to her diabetes treatment and represents a coincidental new eye condition', false, 'Ruled out because this is a well-recognised, specific phenomenon directly related to rapid glycaemic improvement in patients with pre-existing retinopathy, not an unrelated coincidental finding.', 3),
('f7000000-0000-0000-0000-000000000004', 'D', 'Intensive insulin therapy should be immediately stopped due to this worsening', false, 'Ruled out because although close monitoring is needed during this transient period, intensive glycaemic control remains important for long-term outcomes; the appropriate response is close ophthalmological surveillance, not abandoning improved glycaemic control.', 4),
('f7000000-0000-0000-0000-000000000004', 'E', 'This represents an allergic reaction to insulin affecting the eyes', false, 'Ruled out because this is not an allergic phenomenon; it reflects a specific, recognised retinal response to rapid glycaemic change, not a hypersensitivity reaction.', 5),
('f7000000-0000-0000-0000-000000000005', 'A', 'Simple cataract progression', false, 'Ruled out because cataract typically causes gradual, progressive visual blurring rather than this sudden loss with a specifically red-tinged, hazy view, which is characteristic of vitreous haemorrhage.', 1),
('f7000000-0000-0000-0000-000000000005', 'B', 'Vitreous haemorrhage', true, 'Correct. Sudden painless visual loss with a hazy, red-tinged fundal view obscuring retinal detail, in a patient with known proliferative diabetic retinopathy, is characteristic of vitreous haemorrhage, resulting from bleeding of fragile new (neovascular) vessels into the vitreous cavity, a recognised complication of proliferative retinopathy requiring urgent ophthalmological assessment.', 2),
('f7000000-0000-0000-0000-000000000005', 'C', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes sudden painless visual loss with a pale retina and cherry-red spot (once visualised), not this hazy, red-tinged obscured view characteristic of vitreous haemorrhage.', 3),
('f7000000-0000-0000-0000-000000000005', 'D', 'Simple refractive error change', false, 'Ruled out because a refractive error change would not cause this sudden, severe visual loss with an obscured, red-tinged fundal view.', 4),
('f7000000-0000-0000-0000-000000000005', 'E', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful visual loss with a relative afferent pupillary defect, not this specific hazy, red-tinged fundal appearance characteristic of vitreous haemorrhage.', 5),
('f7000000-0000-0000-0000-000000000006', 'A', 'Screening only if visual symptoms develop', false, 'Ruled out because diabetic retinopathy is often asymptomatic until relatively advanced, making regular, structured screening (rather than symptom-triggered assessment) essential for early detection of treatable disease.', 1),
('f7000000-0000-0000-0000-000000000006', 'B', 'Annual screening', true, 'Correct. Standard diabetic eye screening programmes recommend annual screening for patients without significant retinopathy, allowing timely detection of new or progressing retinopathy; screening frequency may be increased if retinopathy is identified, reflecting a risk-stratified approach.', 2),
('f7000000-0000-0000-0000-000000000006', 'C', 'Once every 5 years', false, 'Ruled out because this interval is too infrequent to reliably detect and allow timely treatment of progressive diabetic retinopathy, which can develop and progress significantly within a shorter timeframe.', 3),
('f7000000-0000-0000-0000-000000000006', 'D', 'Once every 10 years', false, 'Ruled out because this interval would risk missing significant progression of retinopathy that could benefit from earlier intervention, given how much change can occur over such a long period.', 4),
('f7000000-0000-0000-0000-000000000006', 'E', 'Screening is not needed if HbA1c is well controlled', false, 'Ruled out because although good glycaemic control reduces retinopathy risk, regular screening remains recommended for all patients with diabetes, as some degree of risk persists even with good control, and screening detects existing disease requiring monitoring or treatment.', 5),
('f7000000-0000-0000-0000-000000000007', 'A', 'Mild background retinopathy with low progression risk', false, 'Ruled out because venous beading and cotton wool spots indicate a more severe stage than simple mild background retinopathy (which would typically show only microaneurysms and occasional haemorrhages), reflecting significant ischaemia and higher progression risk.', 1),
('f7000000-0000-0000-0000-000000000007', 'B', 'Established proliferative retinopathy', false, 'Ruled out because proliferative retinopathy is specifically defined by neovascularisation, which is explicitly absent here; this is a pre-proliferative (severe non-proliferative) stage, one step before proliferative disease develops.', 2),
('f7000000-0000-0000-0000-000000000007', 'C', 'Normal retinal ageing changes', false, 'Ruled out because venous beading and cotton wool spots are specific pathological findings related to diabetic retinal ischaemia, not normal ageing changes.', 3),
('f7000000-0000-0000-0000-000000000007', 'D', 'Resolved, healed retinopathy requiring no further monitoring', false, 'Ruled out because these findings indicate active, significant disease with high progression risk, requiring closer monitoring, not resolved disease requiring no further follow-up.', 4),
('f7000000-0000-0000-0000-000000000007', 'E', 'Pre-proliferative (severe non-proliferative) diabetic retinopathy, indicating a higher risk of progression to proliferative disease', true, 'Correct. Venous beading (irregular dilation and constriction of retinal veins) and cotton wool spots (representing areas of retinal nerve fibre layer ischaemia) are features of pre-proliferative (severe non-proliferative) diabetic retinopathy, indicating more significant retinal ischaemia and a higher risk of progression to proliferative disease, warranting closer monitoring.', 5),
('f7000000-0000-0000-0000-000000000008', 'A', 'More frequent retinopathy screening is recommended during pregnancy, given the increased risk of rapid progression', true, 'Correct. Pregnancy is a recognised risk factor for rapid progression of diabetic retinopathy, related to hormonal and haemodynamic changes; more frequent screening (typically each trimester, or more often if retinopathy is present or progressing) is recommended during pregnancy to detect and manage any progression promptly.', 1),
('f7000000-0000-0000-0000-000000000008', 'B', 'No additional screening is needed during pregnancy beyond the standard annual schedule', false, 'Ruled out because pregnancy specifically increases the risk of retinopathy progression, warranting more frequent screening than the standard non-pregnant annual schedule.', 2),
('f7000000-0000-0000-0000-000000000008', 'C', 'Screening should be stopped entirely during pregnancy due to radiation concerns', false, 'Ruled out because standard diabetic eye screening (fundus photography) does not involve ionising radiation and is safe during pregnancy; screening should be increased, not stopped, during this higher-risk period.', 3),
('f7000000-0000-0000-0000-000000000008', 'D', 'Screening is only relevant after delivery, not during pregnancy itself', false, 'Ruled out because retinopathy progression risk is specifically elevated during pregnancy itself, making screening during this period important, not solely after delivery.', 4),
('f7000000-0000-0000-0000-000000000008', 'E', 'Pregnancy has no effect on diabetic retinopathy risk or progression', false, 'Ruled out because pregnancy is a well-recognised risk factor for retinopathy progression, making this statement incorrect and the increased screening frequency clinically important.', 5),
('f7000000-0000-0000-0000-000000000009', 'A', 'Primary open-angle glaucoma unrelated to his diabetic eye disease', false, 'Ruled out because although open-angle glaucoma is common, the specific finding of new iris vessels (rubeosis iridis) in a patient with proliferative diabetic retinopathy points specifically to neovascular glaucoma as a direct complication of his retinal ischaemia, not a coincidental separate primary open-angle process.', 1),
('f7000000-0000-0000-0000-000000000009', 'B', 'Acute angle-closure glaucoma from an unrelated cause', false, 'Ruled out because although angle closure can occur secondary to neovascular changes, the underlying and directly relevant diagnosis here, given the iris neovascularisation in this context, is neovascular glaucoma driven by his diabetic retinal ischaemia.', 2),
('f7000000-0000-0000-0000-000000000009', 'C', 'Simple age-related iris changes with no pathological significance', false, 'Ruled out because new iris vessel growth (rubeosis iridis) is a specific, significant pathological finding requiring prompt recognition and treatment, not a benign age-related change.', 3),
('f7000000-0000-0000-0000-000000000009', 'D', 'Neovascular glaucoma', true, 'Correct. New blood vessel growth on the iris (rubeosis iridis) with rising intraocular pressure, in a patient with longstanding proliferative diabetic retinopathy, is characteristic of neovascular glaucoma, a serious complication where retinal ischaemia drives VEGF-mediated neovascularisation not only in the retina but also in the iris and anterior chamber angle, obstructing normal aqueous outflow and raising intraocular pressure.', 4),
('f7000000-0000-0000-0000-000000000009', 'E', 'Conjunctivitis', false, 'Ruled out because conjunctivitis causes redness and discharge from the conjunctiva, not the specific combination of iris neovascularisation and rising intraocular pressure described here.', 5),
('f7000000-0000-0000-0000-000000000010', 'A', 'Screening is not needed until 10 years after diagnosis, regardless of diabetes type', false, 'Ruled out because this would risk missing retinopathy that may already be present at diagnosis in type 2 diabetes, given its often prolonged asymptomatic pre-diagnosis period.', 1),
('f7000000-0000-0000-0000-000000000010', 'B', 'Screening is only needed if the patient reports visual symptoms', false, 'Ruled out because diabetic retinopathy is often asymptomatic in earlier, treatable stages, making proactive screening (rather than symptom-triggered assessment) the appropriate approach from diagnosis onward.', 2),
('f7000000-0000-0000-0000-000000000010', 'C', 'Screening should be arranged at or shortly after diagnosis, given that type 2 diabetes may have been present subclinically for some time before diagnosis', true, 'Correct. Unlike type 1 diabetes (where screening typically begins some years after diagnosis, reflecting its more clearly defined onset), type 2 diabetes often has a prolonged asymptomatic period before diagnosis, meaning some degree of retinopathy may already be present at the time of diagnosis; screening should therefore be arranged at or shortly after diagnosis, not delayed.', 3),
('f7000000-0000-0000-0000-000000000010', 'D', 'Screening should be delayed until HbA1c is well controlled', false, 'Ruled out because screening should not be delayed pending glycaemic control optimisation; baseline retinal assessment is important at or shortly after diagnosis regardless of current control status.', 4),
('f7000000-0000-0000-0000-000000000010', 'E', 'Screening recommendations are identical for type 1 and type 2 diabetes, with screening starting only several years after diagnosis in both cases', false, 'Ruled out because the timing differs between the two types, specifically because type 2 diabetes often has a significant asymptomatic period before diagnosis, unlike the typically more acute presentation of type 1 diabetes.', 5),
('f7000000-0000-0000-0000-000000000011', 'A', 'It directly strengthens the macula through a structural, mechanical effect', false, 'Ruled out because anti-VEGF agents work through a specific biochemical mechanism (blocking VEGF signalling), not a direct mechanical/structural strengthening effect on macular tissue.', 1),
('f7000000-0000-0000-0000-000000000011', 'B', 'It works by killing bacteria within the eye', false, 'Ruled out because diabetic macular oedema is not an infective process, and anti-VEGF agents have no antimicrobial action; this describes an entirely different (antibiotic) mechanism.', 2),
('f7000000-0000-0000-0000-000000000011', 'C', 'It works by directly lowering blood glucose levels within the eye', false, 'Ruled out because anti-VEGF agents do not have a direct glucose-lowering mechanism; their action is specifically on the VEGF signalling pathway affecting vascular permeability and neovascularisation.', 3),
('f7000000-0000-0000-0000-000000000011', 'D', 'It blocks vascular endothelial growth factor, reducing vascular permeability and fluid leakage into the macula', true, 'Correct. Anti-VEGF agents (e.g. ranibizumab, aflibercept) bind to and block VEGF, a signalling protein that increases vascular permeability and drives abnormal blood vessel growth in response to retinal ischaemia; blocking VEGF reduces vascular leakage into the macula, helping to resolve macular oedema and improve or stabilise vision.', 4),
('f7000000-0000-0000-0000-000000000011', 'E', 'It works by physically draining excess fluid from the eye through a mechanical shunt', false, 'Ruled out because anti-VEGF injections do not create a physical drainage pathway; their effect is pharmacological, reducing the underlying vascular leakage at a molecular level.', 5),
('f7000000-0000-0000-0000-000000000012', 'A', 'Rhegmatogenous retinal detachment unrelated to his diabetic disease', false, 'Ruled out because although rhegmatogenous detachment is a different mechanism (from a retinal break/tear), the strong context of proliferative diabetic retinopathy with fibrovascular tissue makes tractional detachment the more likely and directly related mechanism here.', 1),
('f7000000-0000-0000-0000-000000000012', 'B', 'Vitreous haemorrhage alone', false, 'Ruled out because vitreous haemorrhage typically causes a hazy, red-tinged view obscuring retinal detail, not this distinct dome-shaped retinal elevation with a relatively clear vitreous, which is characteristic of tractional detachment.', 2),
('f7000000-0000-0000-0000-000000000012', 'C', 'Simple cataract', false, 'Ruled out because cataract causes gradual visual blurring from lens opacity, not this specific finding of a dome-shaped retinal elevation.', 3),
('f7000000-0000-0000-0000-000000000012', 'D', 'Central serous retinopathy', false, 'Ruled out because central serous retinopathy causes a more localised, typically macular, serous detachment, not this pattern specifically associated with fibrovascular traction from proliferative diabetic retinopathy.', 4),
('f7000000-0000-0000-0000-000000000012', 'E', 'Tractional retinal detachment', true, 'Correct. A dense, elevated, dome-shaped area of retinal detachment (with a relatively clear vitreous, distinguishing it from vitreous haemorrhage) in a patient with proliferative diabetic retinopathy is characteristic of tractional retinal detachment, caused by contraction of fibrovascular tissue associated with the neovascularisation pulling the retina away from the underlying retinal pigment epithelium; this requires urgent ophthalmological/vitreoretinal surgical assessment.', 5),
('f7000000-0000-0000-0000-000000000013', 'A', 'Central retinal artery occlusion', true, 'Correct. Sudden, painless, profound visual loss with a pale, oedematous retina and a cherry-red spot at the macula (where the thin fovea allows the underlying choroidal circulation to remain visible against the surrounding ischaemic pallor) is characteristic of central retinal artery occlusion, an ophthalmic emergency and a retinal equivalent of stroke, requiring urgent assessment and consideration of thrombolysis where within the treatment window, alongside cardiovascular risk factor assessment.', 1),
('f7000000-0000-0000-0000-000000000013', 'B', 'Central retinal vein occlusion', false, $x$Ruled out because CRVO causes widespread retinal haemorrhages with a 'blood and thunder' appearance and disc swelling, not this pale retina with a cherry-red spot, which is specific to arterial occlusion.$x$, 2),
('f7000000-0000-0000-0000-000000000013', 'C', 'Vitreous haemorrhage', false, 'Ruled out because vitreous haemorrhage causes a hazy, red-tinged obscured view, not the specific pale retina with cherry-red spot appearance characteristic of CRAO.', 3),
('f7000000-0000-0000-0000-000000000013', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes a visual field defect described as a curtain or shadow, with a specific detached retinal appearance, not the pale retina with cherry-red spot seen in CRAO.', 4),
('f7000000-0000-0000-0000-000000000013', 'E', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful visual loss with a relative afferent pupillary defect and often initially normal fundoscopy (in retrobulbar cases), not this specific pale retina with cherry-red spot appearance.', 5),
('f7000000-0000-0000-0000-000000000014', 'A', 'Central retinal artery occlusion', false, $x$Ruled out because CRAO causes a pale, ischaemic retina with a cherry-red spot, a very different fundal appearance from the haemorrhagic 'blood and thunder' picture of CRVO.$x$, 1),
('f7000000-0000-0000-0000-000000000014', 'B', 'Central retinal vein occlusion', true, $x$Correct. Widespread retinal haemorrhages in all four quadrants with dilated, tortuous veins and disc swelling ('blood and thunder' fundus) is characteristic of central retinal vein occlusion, resulting from thrombotic obstruction of the central retinal vein, associated with risk factors including hypertension, diabetes and glaucoma.$x$, 2),
('f7000000-0000-0000-0000-000000000014', 'C', 'Vitreous haemorrhage', false, 'Ruled out because vitreous haemorrhage causes a hazy view obscuring retinal detail, not this specific pattern of visible widespread intraretinal haemorrhages with disc swelling.', 3),
('f7000000-0000-0000-0000-000000000014', 'D', 'Diabetic retinopathy alone', false, 'Ruled out because although diabetes is a risk factor for CRVO, the specific acute, widespread haemorrhagic pattern described (rather than the more chronic, scattered changes of diabetic retinopathy) is characteristic of an acute venous occlusion event.', 4),
('f7000000-0000-0000-0000-000000000014', 'E', 'Age-related macular degeneration', false, $x$Ruled out because AMD causes central visual distortion/loss related to macular changes (drusen, or in the wet form, subretinal neovascularisation and haemorrhage), not this specific widespread 'blood and thunder' pattern across all four retinal quadrants.$x$, 5),
('f7000000-0000-0000-0000-000000000015', 'A', 'Migraine with aura', false, 'Ruled out because migrainous visual aura typically involves positive visual phenomena (zigzag lines, scintillations) rather than this pattern of transient, painless, curtain-like visual loss, and is not specifically linked to carotid disease.', 1),
('f7000000-0000-0000-0000-000000000015', 'B', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes persistent, progressive visual field loss (often also described with a curtain sensation) rather than this specific fully resolving pattern within minutes; the transient, resolving nature and vascular risk context point to amaurosis fugax.', 2),
('f7000000-0000-0000-0000-000000000015', 'C', 'Amaurosis fugax', true, 'Correct. Transient, painless monocular visual loss, classically described as a curtain descending and resolving completely within minutes, in a patient with known carotid artery disease, is characteristic of amaurosis fugax, typically caused by transient retinal ischaemia from embolic material (often from carotid atherosclerotic plaque); this represents a form of TIA and warrants urgent vascular risk assessment and secondary prevention, similar to a cerebral TIA.', 3),
('f7000000-0000-0000-0000-000000000015', 'D', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful, more prolonged (days to weeks) visual loss, not this specific transient (minutes), painless, fully resolving pattern linked to vascular risk factors.', 4),
('f7000000-0000-0000-0000-000000000015', 'E', 'Simple ocular migraine unrelated to vascular disease', false, 'Ruled out because the strong context of known carotid artery disease, combined with the classic transient monocular visual loss pattern, points specifically to an embolic/vascular cause (amaurosis fugax) rather than a primary ocular migraine phenomenon.', 5),
('f7000000-0000-0000-0000-000000000016', 'A', 'Non-arteritic anterior ischaemic optic neuropathy, requiring only observation', false, 'Ruled out because the accompanying systemic features (temporal headache, scalp tenderness, jaw claudication, markedly raised ESR) strongly suggest an arteritic (GCA-related) rather than non-arteritic cause; this distinction is critical, as the arteritic form requires urgent steroid treatment, unlike the non-arteritic form.', 1),
('f7000000-0000-0000-0000-000000000016', 'B', 'Simple cataract', false, 'Ruled out because cataract causes gradual, not sudden, visual blurring, and would not explain the accompanying systemic symptoms and markedly raised ESR.', 2),
('f7000000-0000-0000-0000-000000000016', 'C', 'Migraine-related visual disturbance', false, 'Ruled out because migraine visual disturbance is typically transient and does not cause persistent visual loss, nor would it explain the systemic features (jaw claudication, raised ESR) described here, which are specific to GCA.', 3),
('f7000000-0000-0000-0000-000000000016', 'D', 'Arteritic anterior ischaemic optic neuropathy secondary to giant cell arteritis, requiring immediate high-dose corticosteroids', true, 'Correct. Sudden painless visual loss in an older patient with new temporal headache, scalp tenderness, jaw claudication and a markedly raised ESR is characteristic of giant cell arteritis causing arteritic anterior ischaemic optic neuropathy; immediate high-dose corticosteroids should be started without waiting for biopsy confirmation, given the high risk of the fellow eye being affected if treatment is delayed.', 4),
('f7000000-0000-0000-0000-000000000016', 'E', 'Simple age-related macular degeneration', false, 'Ruled out because AMD causes more gradual central visual distortion, not this sudden visual loss with accompanying systemic GCA features requiring urgent treatment.', 5),
('f7000000-0000-0000-0000-000000000017', 'A', 'Fourth cranial nerve palsy, requiring no urgent investigation', false, $x$Ruled out because a fourth nerve (trochlear) palsy causes vertical diplopia with subtle hypertropia, not this specific 'down and out' position with ptosis and pupil involvement, which is characteristic of a third nerve palsy.$x$, 1),
('f7000000-0000-0000-0000-000000000017', 'B', 'Sixth cranial nerve palsy, requiring no urgent investigation', false, $x$Ruled out because a sixth nerve (abducens) palsy causes an inability to abduct the eye (medially deviated at rest), not this specific 'down and out' position with ptosis and pupillary involvement characteristic of third nerve palsy.$x$, 2),
('f7000000-0000-0000-0000-000000000017', 'C', 'Third nerve palsy, but pupillary involvement is reassuring and suggests a benign microvascular cause', false, 'Ruled out because this is the opposite of the correct clinical reasoning: pupil-sparing third nerve palsy is more typically associated with benign microvascular causes (e.g. diabetes, hypertension), whereas pupil-involving palsy specifically raises concern for a compressive cause requiring urgent exclusion.', 3),
('f7000000-0000-0000-0000-000000000017', 'D', 'Horner syndrome, requiring no urgent investigation', false, $x$Ruled out because Horner syndrome causes ptosis with miosis (constricted pupil), not the dilated pupil and 'down and out' eye position described here, which is characteristic of a third nerve palsy.$x$, 4),
('f7000000-0000-0000-0000-000000000017', 'E', 'Third cranial nerve palsy, with pupillary involvement raising concern for a compressive cause such as a posterior communicating artery aneurysm', true, $x$Correct. A third nerve palsy causing a 'down and out' eye position with ptosis and, critically, a dilated, unreactive (pupil-involving) pupil raises significant concern for a compressive lesion, classically a posterior communicating artery aneurysm, as the parasympathetic pupillary fibres run peripherally in the nerve and are particularly vulnerable to external compression; this requires urgent neuroimaging (CT/MR angiography) to exclude an aneurysm, given the risk of rupture.$x$, 5),
('f7000000-0000-0000-0000-000000000018', 'A', 'Microvascular ischaemia (diabetic mononeuropathy) affecting the third cranial nerve', true, $x$Correct. A pupil-sparing third nerve palsy (normal pupil size and reactivity, with extraocular muscle and levator involvement) in a patient with longstanding, poorly controlled diabetes is characteristic of microvascular ischaemic third nerve palsy, related to small vessel disease affecting the nerve's blood supply, typically improving over weeks to months without specific treatment beyond risk factor control.$x$, 1),
('f7000000-0000-0000-0000-000000000018', 'B', 'Posterior communicating artery aneurysm', false, 'Ruled out because aneurysmal compression classically causes early pupillary involvement (dilated, unreactive pupil), which is specifically absent here; the pupil-sparing pattern is more consistent with a microvascular cause.', 2),
('f7000000-0000-0000-0000-000000000018', 'C', 'Raised intracranial pressure causing uncal herniation', false, 'Ruled out because this would typically also cause pupillary involvement (a dilated, unreactive pupil) as part of the compressive third nerve palsy, along with signs of significantly raised intracranial pressure, not this isolated pupil-sparing pattern.', 3),
('f7000000-0000-0000-0000-000000000018', 'D', 'Myasthenia gravis', false, 'Ruled out because myasthenia gravis causes fatigable weakness, often affecting multiple ocular muscles bilaterally with variable ptosis, not this specific unilateral pattern with a discrete, sudden-onset pupil-sparing third nerve palsy typical of a mononeuropathy.', 4),
('f7000000-0000-0000-0000-000000000018', 'E', 'Multiple sclerosis', false, 'Ruled out because although MS can cause various ocular motor abnormalities, the specific presentation described (sudden pupil-sparing third nerve palsy in an older patient with diabetes) is much more characteristic of microvascular ischaemic mononeuropathy.', 5),
('f7000000-0000-0000-0000-000000000019', 'A', 'Third cranial nerve palsy', false, 'Ruled out because a third nerve palsy would cause impaired adduction (and other extraocular movements) of the affected eye on all gaze directions, along with ptosis and often pupil involvement, not this isolated, gaze-direction-specific pattern with preserved convergence.', 1),
('f7000000-0000-0000-0000-000000000019', 'B', 'Internuclear ophthalmoplegia', true, 'Correct. Impaired adduction of one eye on contralateral gaze with nystagmus of the abducting fellow eye, and preserved convergence, is the classic sign of internuclear ophthalmoplegia, caused by a lesion of the medial longitudinal fasciculus (here, on the right, impairing right eye adduction) -- a highly characteristic finding in multiple sclerosis in a young patient.', 2),
('f7000000-0000-0000-0000-000000000019', 'C', 'Sixth cranial nerve palsy', false, 'Ruled out because a sixth nerve palsy causes impaired abduction (not adduction) of the affected eye, the opposite pattern to that described.', 3),
('f7000000-0000-0000-0000-000000000019', 'D', 'Myasthenia gravis', false, 'Ruled out because although MG can cause variable diplopia, it would not produce this specific, reproducible pattern linked to a defined brainstem tract (MLF) with preserved convergence, and would typically show fatigability rather than this static localising sign.', 4),
('f7000000-0000-0000-0000-000000000019', 'E', 'Horner syndrome', false, 'Ruled out because Horner syndrome causes ptosis, miosis and anhidrosis, not a disorder of conjugate eye movements or diplopia.', 5),
('f7000000-0000-0000-0000-000000000020', 'A', 'There is no vision-related concern; papilloedema is a benign finding requiring no action', false, 'Ruled out because papilloedema reflects raised intracranial pressure and carries a genuine risk of progressive visual loss if untreated, requiring active assessment and management, not being disregarded as benign.', 1),
('f7000000-0000-0000-0000-000000000020', 'B', 'The visual symptoms are unrelated to the papilloedema and require separate, unrelated ophthalmological investigation', false, 'Ruled out because the transient visual blurring and papilloedema are directly related, both reflecting the effects of raised intracranial pressure on the optic nerves, not separate, unrelated processes.', 2),
('f7000000-0000-0000-0000-000000000020', 'C', 'Progressive, potentially irreversible visual field loss from chronic papilloedema, requiring urgent assessment and treatment', true, 'Correct. Papilloedema (optic disc swelling from raised intracranial pressure, here likely idiopathic intracranial hypertension given the risk profile) can cause progressive, potentially irreversible visual field loss if the underlying raised pressure is not identified and treated; urgent ophthalmological and neurological assessment, including visual field testing and treatment of the underlying cause, is needed to protect vision.', 3),
('f7000000-0000-0000-0000-000000000020', 'D', 'Papilloedema in this context indicates a primary retinal, rather than optic nerve, problem', false, 'Ruled out because papilloedema specifically refers to swelling of the optic nerve head from raised intracranial pressure, not a primary retinal pathology.', 4),
('f7000000-0000-0000-0000-000000000020', 'E', 'No monitoring of vision is required once the diagnosis is suspected', false, 'Ruled out because regular visual field monitoring is an important part of managing papilloedema/IIH, tracking for any progression of visual field loss and guiding treatment intensity.', 5),
('f7000000-0000-0000-0000-000000000021', 'A', 'A lesion of the optic nerve on the same side as the visual field loss', false, 'Ruled out because an optic nerve lesion causes monocular visual loss in the eye on that side, not a homonymous (both eyes, same side) visual field defect.', 1),
('f7000000-0000-0000-0000-000000000021', 'B', 'A lesion at the optic chiasm', false, 'Ruled out because chiasmal lesions classically cause bitemporal hemianopia (affecting the temporal fields of both eyes), not the homonymous pattern described here.', 2),
('f7000000-0000-0000-0000-000000000021', 'C', 'A lesion in the right optic tract, radiation, or occipital cortex (post-chiasmal)', true, 'Correct. A homonymous hemianopia (loss of the same side of the visual field in both eyes) localises to a lesion posterior to the optic chiasm on the side opposite the visual field defect -- here, a right-sided lesion affecting the optic tract, optic radiations, or occipital cortex, causing loss of the left visual field in both eyes, most commonly from a vascular event (stroke) in this location.', 3),
('f7000000-0000-0000-0000-000000000021', 'D', 'A lesion of the contralateral optic nerve', false, 'Ruled out because optic nerve lesions cause monocular, not homonymous binocular, visual field defects; homonymous hemianopia specifically localises to a post-chiasmal lesion affecting the visual pathway after the fibres have partially crossed at the chiasm.', 4),
('f7000000-0000-0000-0000-000000000021', 'E', 'A lesion in the anterior chamber of the eye itself', false, 'Ruled out because anterior chamber pathology would cause more generalised or localised visual disturbance related to that specific eye, not this precisely lateralising, binocular homonymous visual field pattern, which is a neurological (visual pathway) localising sign.', 5),
('f7000000-0000-0000-0000-000000000022', 'A', 'Third cranial nerve palsy', false, 'Ruled out because a third nerve palsy causes ptosis with a dilated (not constricted) pupil and other extraocular movement abnormalities, the opposite pupillary finding to Horner syndrome.', 1),
('f7000000-0000-0000-0000-000000000022', 'B', 'Horner syndrome', true, 'Correct. Ptosis, miosis and anhidrosis (reduced sweating) on the same side is the classic triad of Horner syndrome, resulting from disruption of the sympathetic nerve supply to the eye and face; in this context, it is likely related to injury of the sympathetic chain associated with the brachial plexus injury during a difficult delivery.', 2),
('f7000000-0000-0000-0000-000000000022', 'C', 'Myasthenia gravis', false, 'Ruled out because myasthenia gravis causes fatigable ptosis without the specific miosis and anhidrosis seen in Horner syndrome, and would not typically be linked to this acute traumatic context.', 3),
('f7000000-0000-0000-0000-000000000022', 'D', 'Simple congenital ptosis unrelated to the delivery', false, 'Ruled out because the clear temporal relationship to a difficult delivery with associated brachial plexus injury, combined with the classic triad (ptosis, miosis, anhidrosis), points specifically to Horner syndrome from sympathetic chain disruption, not an unrelated congenital finding.', 4),
('f7000000-0000-0000-0000-000000000022', 'E', $x$Bell's palsy$x$, false, $x$Ruled out because Bell's palsy causes lower motor neuron facial weakness (affecting the whole side of the face, including forehead), not this specific triad of ptosis, miosis and anhidrosis affecting the sympathetic pathway.$x$, 5),
('f7000000-0000-0000-0000-000000000023', 'A', 'Arteritic anterior ischaemic optic neuropathy from giant cell arteritis', false, 'Ruled out because there is no mention of the systemic features (headache, scalp tenderness, jaw claudication, raised ESR) that would suggest an arteritic (GCA-related) cause; the absence of these features, along with the specific altitudinal pattern, points to the non-arteritic form, which does not require urgent high-dose steroid treatment in the same way.', 1),
('f7000000-0000-0000-0000-000000000023', 'B', 'Central retinal artery occlusion', false, 'Ruled out because CRAO typically causes more global, profound visual loss with a pale retina and cherry-red spot, rather than this specific altitudinal (partial visual field) defect pattern characteristic of AION.', 2),
('f7000000-0000-0000-0000-000000000023', 'C', 'Retinal detachment', false, 'Ruled out because although retinal detachment can also cause a curtain-like visual field defect, the specific finding of optic disc swelling (rather than a detached retina appearance) points to AION as the diagnosis here.', 3),
('f7000000-0000-0000-0000-000000000023', 'D', 'Central retinal vein occlusion', false, $x$Ruled out because CRVO causes widespread haemorrhages ('blood and thunder' appearance), not this specific altitudinal pattern with disc swelling characteristic of AION.$x$, 4),
('f7000000-0000-0000-0000-000000000023', 'E', 'Non-arteritic anterior ischaemic optic neuropathy', true, $x$Correct. Sudden, painless, altitudinal visual field loss with optic disc swelling, in the absence of systemic features suggesting giant cell arteritis (no headache, scalp tenderness, jaw claudication, normal inflammatory markers), is characteristic of non-arteritic anterior ischaemic optic neuropathy, related to small vessel ischaemia of the optic nerve head, often associated with vascular risk factors and a crowded, small optic disc anatomy ('disc at risk').$x$, 5),
('f7000000-0000-0000-0000-000000000024', 'A', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes sudden, painless, profound visual loss due to acute retinal ischaemia, not the subacute, painful presentation with a demyelinating nerve lesion described here.', 1),
('f7000000-0000-0000-0000-000000000024', 'B', 'Anterior ischaemic optic neuropathy', false, 'Ruled out because AION typically causes sudden, painless visual loss with optic disc swelling, not this painful presentation with a demyelinating lesion on MRI, which is specific to optic neuritis.', 2),
('f7000000-0000-0000-0000-000000000024', 'C', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes painless visual field loss described as a curtain or shadow, without pain on eye movement or a demyelinating lesion on MRI.', 3),
('f7000000-0000-0000-0000-000000000024', 'D', 'Optic neuritis', true, 'Correct. Subacute, painful (worse on eye movement) unilateral visual loss with reduced colour vision, a relative afferent pupillary defect, and a demyelinating optic nerve lesion on MRI is classic for optic neuritis, commonly the first presentation of multiple sclerosis, though it can also occur in isolation or with other demyelinating conditions.', 4),
('f7000000-0000-0000-0000-000000000024', 'E', 'Migraine with visual aura', false, 'Ruled out because migrainous visual aura is transient (lasting minutes), fully reversible, and would not cause a persistent relative afferent pupillary defect or a demyelinating lesion on imaging.', 5),
('f7000000-0000-0000-0000-000000000025', 'A', 'Cavernous sinus syndrome, affecting multiple cranial nerves that pass through this structure', true, 'Correct. The cavernous sinus contains the third, fourth and sixth cranial nerves (controlling eye movement) along with the ophthalmic and maxillary divisions of the trigeminal nerve (sensory to the forehead/face); a lesion here (from causes including thrombosis, tumour, aneurysm, or infection) can cause a combination of ophthalmoplegia (here, third nerve palsy) and facial sensory loss, as seen in this patient, requiring urgent imaging and identification of the underlying cause.', 1),
('f7000000-0000-0000-0000-000000000025', 'B', 'Isolated third nerve palsy alone, unrelated to the facial numbness', false, 'Ruled out because the combination of third nerve palsy with trigeminal sensory loss (forehead numbness) specifically reflects the anatomical grouping of these structures within the cavernous sinus, rather than being two separate, unrelated findings.', 2),
('f7000000-0000-0000-0000-000000000025', 'C', 'Simple migraine with associated cranial nerve palsy', false, 'Ruled out because migraine does not cause this combination of structural findings on MRI with multiple cranial nerve involvement; the imaging-confirmed cavernous sinus lesion provides a clear structural explanation.', 3),
('f7000000-0000-0000-0000-000000000025', 'D', $x$Bell's palsy with coincidental third nerve palsy$x$, false, $x$Ruled out because Bell's palsy affects the facial (seventh) nerve causing lower motor neuron facial weakness, not the combination of third nerve and trigeminal sensory findings described here, which specifically localise to the cavernous sinus.$x$, 4),
('f7000000-0000-0000-0000-000000000025', 'E', 'Simple tension headache with unrelated eye findings', false, 'Ruled out because the specific combination of ophthalmoplegia, pupillary involvement and trigeminal sensory loss, with a confirmed structural lesion on MRI, indicates a specific anatomical syndrome (cavernous sinus syndrome), not a primary headache disorder with coincidental findings.', 5),
('f7000000-0000-0000-0000-000000000026', 'A', 'Conjunctivitis', false, 'Ruled out because simple conjunctivitis does not cause an irregular pupil, ciliary flush, or anterior chamber cells, which are specific to anterior chamber inflammation (uveitis).', 1),
('f7000000-0000-0000-0000-000000000026', 'B', 'Acute angle-closure glaucoma', false, 'Ruled out because although this also causes a painful red eye, it typically presents with a fixed, mid-dilated (not irregular, constricted) pupil, a hazy cornea and markedly raised intraocular pressure, a different pattern from anterior uveitis.', 2),
('f7000000-0000-0000-0000-000000000026', 'C', 'Episcleritis', false, 'Ruled out because episcleritis typically causes mild redness and discomfort without significant photophobia, pupil changes, or anterior chamber cells, a much milder condition than anterior uveitis.', 3),
('f7000000-0000-0000-0000-000000000026', 'D', 'Bacterial keratitis', false, 'Ruled out because keratitis typically shows a corneal infiltrate/ulcer on examination, not primarily this pattern of anterior chamber inflammation with an irregular pupil and ciliary flush.', 4),
('f7000000-0000-0000-0000-000000000026', 'E', 'Acute anterior uveitis', true, 'Correct. Painful red eye with photophobia, an irregular pupil (from posterior synechiae), ciliary flush, and anterior chamber cells on slit-lamp examination, in a patient with ankylosing spondylitis (an HLA-B27-associated condition), is characteristic of acute anterior uveitis, requiring urgent ophthalmology assessment and treatment (typically topical corticosteroids and mydriatics) to reduce inflammation and prevent complications.', 5),
('f7000000-0000-0000-0000-000000000027', 'A', 'Posterior uveitis (chorioretinitis)', true, 'Correct. Gradual, painless visual blurring with floaters, vitreous cells, and inflammatory changes affecting the choroid and retina (perivascular sheathing), in a patient with known sarcoidosis (a recognised systemic cause), is characteristic of posterior uveitis, affecting the posterior segment of the eye rather than primarily the anterior chamber.', 1),
('f7000000-0000-0000-0000-000000000027', 'B', 'Anterior uveitis', false, 'Ruled out because anterior uveitis primarily affects the anterior chamber (cells there, pupillary changes), typically presenting with more pain and photophobia, not this pattern of vitreous cells and posterior segment (choroid/retina) changes described here.', 2),
('f7000000-0000-0000-0000-000000000027', 'C', 'Simple conjunctivitis', false, 'Ruled out because conjunctivitis does not cause vitreous cells or posterior segment inflammatory changes; these findings indicate a more significant intraocular inflammatory process.', 3),
('f7000000-0000-0000-0000-000000000027', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment causes a specific field defect from mechanical separation, not this pattern of vitreous cellular inflammation and perivascular sheathing characteristic of posterior uveitis.', 4),
('f7000000-0000-0000-0000-000000000027', 'E', 'Diabetic retinopathy', false, 'Ruled out because there is no diabetes history given, and the specific inflammatory findings (vitreous cells, perivascular sheathing) in the context of known sarcoidosis point to posterior uveitis, not diabetic vascular changes.', 5),
('f7000000-0000-0000-0000-000000000028', 'A', 'Screening is unnecessary, as JIA-associated uveitis always causes obvious symptoms', false, 'Ruled out because this is precisely the opposite of the clinical reality; JIA-associated uveitis is characteristically often asymptomatic, especially in young children, which is why proactive screening (rather than waiting for symptoms) is specifically recommended.', 1),
('f7000000-0000-0000-0000-000000000028', 'B', 'Screening is only relevant for adults with rheumatoid arthritis, not children with JIA', false, 'Ruled out because this specific screening recommendation relates directly to JIA in children, given its recognised association with often silent uveitis, a distinct consideration from adult rheumatoid arthritis.', 2),
('f7000000-0000-0000-0000-000000000028', 'C', 'JIA-associated uveitis is often asymptomatic, particularly in young children, making regular screening essential to detect and treat it before vision-threatening complications develop', true, 'Correct. Uveitis associated with juvenile idiopathic arthritis (particularly the oligoarticular, ANA-positive subtype) is frequently asymptomatic, especially in young children who may not reliably report visual symptoms; regular, structured ophthalmological screening is therefore essential to detect uveitis early, before complications such as cataract, glaucoma, or band keratopathy develop from chronic, unrecognised inflammation.', 3),
('f7000000-0000-0000-0000-000000000028', 'D', 'This inflammation is a normal finding requiring no specific action', false, 'Ruled out because anterior chamber inflammation identified on screening represents active uveitis requiring treatment to prevent complications, not a normal, inconsequential finding.', 4),
('f7000000-0000-0000-0000-000000000028', 'E', 'Screening is performed only to assess for refractive errors, not inflammation', false, 'Ruled out because the specific purpose of this structured screening programme is to detect uveitis (inflammation), not simply refractive error assessment.', 5),
('f7000000-0000-0000-0000-000000000029', 'A', 'Episcleritis', false, 'Ruled out because episcleritis typically causes milder discomfort (not severe pain) with a brighter red, more superficial appearance, and does not typically wake patients at night; the severity and depth of pain described here is more consistent with scleritis.', 1),
('f7000000-0000-0000-0000-000000000029', 'B', 'Scleritis', true, 'Correct. Severe, deep, boring ocular pain (often worse at night, waking the patient), localised deep red/violet scleral inflammation with tenderness, in a patient with an associated systemic autoimmune condition (rheumatoid arthritis), is characteristic of scleritis, a serious, potentially vision-threatening inflammatory condition requiring prompt ophthalmological assessment and often systemic immunosuppressive treatment.', 2),
('f7000000-0000-0000-0000-000000000029', 'C', 'Simple conjunctivitis', false, 'Ruled out because conjunctivitis causes more diffuse redness with discharge, not this localised, deep, severely painful scleral inflammation.', 3),
('f7000000-0000-0000-0000-000000000029', 'D', 'Corneal abrasion', false, 'Ruled out because a corneal abrasion typically has a clear history of trauma or foreign body sensation with fluorescein staining showing a defect, not this pattern of deep scleral inflammation associated with systemic autoimmune disease.', 4),
('f7000000-0000-0000-0000-000000000029', 'E', 'Acute angle-closure glaucoma', false, 'Ruled out because angle-closure glaucoma causes a fixed, mid-dilated pupil with a hazy cornea and markedly raised intraocular pressure, a different clinical picture from the localised scleral inflammation described here.', 5),
('f7000000-0000-0000-0000-000000000030', 'A', 'Scleritis', false, 'Ruled out because scleritis causes severe pain and deep, violet inflammation that does not blanch with phenylephrine, unlike the mild discomfort and blanching response described here.', 1),
('f7000000-0000-0000-0000-000000000030', 'B', 'Acute anterior uveitis', false, 'Ruled out because anterior uveitis typically causes more significant pain, photophobia, and anterior chamber cells with pupillary changes, not simply mild, superficial, blanching redness.', 2),
('f7000000-0000-0000-0000-000000000030', 'C', 'Bacterial conjunctivitis', false, 'Ruled out because bacterial conjunctivitis typically causes purulent discharge and more diffuse conjunctival redness, not this specific localised, blanching pattern of episcleral vessel injection.', 3),
('f7000000-0000-0000-0000-000000000030', 'D', 'Episcleritis', true, 'Correct. Mild redness and discomfort (without significant pain, photophobia or visual change), with localised, bright red, superficial vascular injection that blanches with topical phenylephrine (distinguishing the superficial episcleral vessels from the deeper scleral vessels of scleritis, which do not blanch), is characteristic of episcleritis, a generally benign, often self-limiting condition.', 4),
('f7000000-0000-0000-0000-000000000030', 'E', 'Corneal ulcer', false, 'Ruled out because a corneal ulcer would show a visible corneal defect/infiltrate, not simply superficial, blanching vascular redness without other corneal signs.', 5),
('f7000000-0000-0000-0000-000000000031', 'A', 'Hyphema, indicating blood in the anterior chamber', false, 'Ruled out because hyphema specifically refers to blood (not white cells) layering in the anterior chamber, typically from trauma, a different finding from the white cell layering (hypopyon) described here.', 1),
('f7000000-0000-0000-0000-000000000031', 'B', 'A normal finding requiring no specific significance', false, 'Ruled out because a hypopyon is a significant finding indicating severe intraocular inflammation, not a normal or inconsequential finding.', 2),
('f7000000-0000-0000-0000-000000000031', 'C', 'Hypopyon, indicating a layered collection of white cells in the anterior chamber from severe inflammation', true, $x$Correct. A hypopyon is a visible layer of white blood cells settling in the anterior chamber, indicating severe intraocular inflammation; in the context of Behcet's disease, this represents a classic, severe form of recurrent anterior uveitis, requiring prompt, often aggressive treatment given the recurrent, potentially vision-threatening nature of ocular Behcet's disease.$x$, 3),
('f7000000-0000-0000-0000-000000000031', 'D', 'Simple conjunctival discharge', false, 'Ruled out because this describes a specific finding within the anterior chamber (visible on slit-lamp examination as a layered collection), not conjunctival discharge, which would be on the ocular surface.', 4),
('f7000000-0000-0000-0000-000000000031', 'E', 'A sign of corneal infection unrelated to uveitis', false, $x$Ruled out because although hypopyon can occur with severe corneal infection/keratitis in some contexts, in this scenario (Behcet's disease with recurrent painful red eye and photophobia) it specifically reflects severe anterior uveitis, a recognised and classic ocular manifestation of Behcet's disease.$x$, 5),
('f7000000-0000-0000-0000-000000000032', 'A', 'Simple viral conjunctivitis unrelated to his other symptoms', false, 'Ruled out because the specific combination of eye involvement with joint pains and urethral discharge, following a preceding infection, points to the broader syndrome of reactive arthritis, not an isolated, unrelated viral conjunctivitis.', 1),
('f7000000-0000-0000-0000-000000000032', 'B', 'Reactive arthritis, with uveitis as part of the classic triad alongside urethritis and arthritis', true, 'Correct. The combination of uveitis (or conjunctivitis), urethritis and arthritis, following a gastrointestinal (or genitourinary) infection, is the classic triad of reactive arthritis; the eye involvement can range from milder conjunctivitis to more significant anterior uveitis, reflecting the broader systemic immune-mediated response following the triggering infection.', 2),
('f7000000-0000-0000-0000-000000000032', 'C', 'Gonococcal conjunctivitis alone, unrelated to his joint symptoms', false, 'Ruled out because although gonococcal infection can cause conjunctivitis, the combination with joint symptoms and the preceding gastrointestinal illness points to the broader reactive arthritis syndrome, not an isolated gonococcal eye infection.', 3),
('f7000000-0000-0000-0000-000000000032', 'D', 'Simple allergic conjunctivitis', false, 'Ruled out because allergic conjunctivitis would not explain the associated urethritis and arthritis, or the preceding infective trigger, pointing instead to reactive arthritis as the unifying diagnosis.', 4),
('f7000000-0000-0000-0000-000000000032', 'E', 'Herpetic keratitis unrelated to his systemic symptoms', false, 'Ruled out because herpetic keratitis is a localised corneal infection, not explaining the systemic pattern of joint and urethral symptoms linked by a preceding infective trigger, which is characteristic of reactive arthritis.', 5),
('f7000000-0000-0000-0000-000000000033', 'A', 'Sympathetic ophthalmia', true, 'Correct. Bilateral granulomatous uveitis developing in the previously uninvolved eye following surgery or penetrating trauma to the other eye is characteristic of sympathetic ophthalmia, a rare but serious autoimmune inflammatory condition thought to result from an immune response against ocular antigens exposed during the surgery/trauma, which then also attacks the fellow eye; it requires prompt, often intensive immunosuppressive treatment given the risk to vision in the originally unaffected eye.', 1),
('f7000000-0000-0000-0000-000000000033', 'B', 'Simple post-surgical inflammation confined to the operated eye', false, 'Ruled out because the inflammation described specifically involves the other, unoperated eye, which is the defining and concerning feature of sympathetic ophthalmia, not simply expected inflammation in the surgical eye itself.', 2),
('f7000000-0000-0000-0000-000000000033', 'C', 'Endophthalmitis affecting the operated eye', false, 'Ruled out because the inflammation described is in the unoperated eye, not the surgical eye; endophthalmitis specifically refers to infection within the operated eye itself.', 3),
('f7000000-0000-0000-0000-000000000033', 'D', 'Coincidental, unrelated bilateral uveitis from another systemic cause', false, 'Ruled out because the clear temporal and causal relationship to recent surgery on the fellow eye, with the specific granulomatous pattern described, is characteristic of sympathetic ophthalmia rather than a coincidental unrelated cause.', 4),
('f7000000-0000-0000-0000-000000000033', 'E', 'Simple allergic reaction to eye drops used postoperatively', false, 'Ruled out because a drop allergy would not cause this specific pattern of granulomatous uveitis in the fellow, unoperated eye; the clinical picture described is specific to sympathetic ophthalmia.', 5),
('f7000000-0000-0000-0000-000000000034', 'A', 'A positive tuberculin skin test', false, $x$Ruled out because this tests for tuberculosis exposure/infection, not a feature specifically supporting a diagnosis of Behcet's disease.$x$, 1),
('f7000000-0000-0000-0000-000000000034', 'B', 'A positive Mantoux test specifically for latent TB', false, $x$Ruled out because this is essentially the same as tuberculin testing for TB, unrelated to the specific pathergy phenomenon associated with Behcet's disease.$x$, 2),
('f7000000-0000-0000-0000-000000000034', 'C', 'A positive rheumatoid factor test', false, $x$Ruled out because rheumatoid factor is associated with rheumatoid arthritis, not a diagnostic criterion or supportive feature for Behcet's disease.$x$, 3),
('f7000000-0000-0000-0000-000000000034', 'D', 'A positive pathergy test (pustule formation at the site of a needle prick 24-48 hours later)', true, $x$Correct. The pathergy test, in which a sterile needle prick produces an exaggerated inflammatory pustular response at the injection site within 24-48 hours, is a characteristic, supportive diagnostic finding in Behcet's disease, reflecting the condition's underlying tendency towards exaggerated cutaneous inflammatory responses, and complements the clinical picture of recurrent oral/genital ulcers and uveitis already described.$x$, 4),
('f7000000-0000-0000-0000-000000000034', 'E', $x$A positive Schirmer's test$x$, false, $x$Ruled out because Schirmer's test assesses tear production (relevant to Sjogren syndrome/dry eye), not a supportive diagnostic feature for Behcet's disease.$x$, 5),
('f7000000-0000-0000-0000-000000000035', 'A', 'Recurrence of active uveitis alone, unrelated to his corticosteroid treatment', false, 'Ruled out because although active uveitis can itself sometimes affect intraocular pressure, the specific, well-recognised association with long-term topical corticosteroid use makes steroid-induced ocular hypertension a key and important consideration requiring specific monitoring, particularly in a patient established on this treatment.', 1),
('f7000000-0000-0000-0000-000000000035', 'B', 'A normal, expected finding requiring no specific monitoring or action', false, 'Ruled out because steroid-induced ocular hypertension is a genuine, monitorable and potentially significant risk requiring active surveillance, not something to be disregarded as inconsequential.', 2),
('f7000000-0000-0000-0000-000000000035', 'C', 'Simple age-related rise in intraocular pressure unrelated to treatment', false, 'Ruled out because although intraocular pressure can have some age-related variation, the specific context of long-term topical corticosteroid use provides a well-recognised, directly relevant explanation that should be specifically considered and monitored for.', 3),
('f7000000-0000-0000-0000-000000000035', 'D', 'Cataract formation causing the pressure rise', false, 'Ruled out because although long-term steroid use can also cause cataract (a separate recognised complication), cataract itself does not typically directly raise intraocular pressure in this manner; the pressure rise here more directly reflects the recognised steroid-induced ocular hypertension mechanism.', 4),
('f7000000-0000-0000-0000-000000000035', 'E', 'Steroid-induced ocular hypertension/glaucoma from long-term topical corticosteroid use', true, 'Correct. Long-term topical corticosteroid use is a recognised cause of raised intraocular pressure (steroid-induced ocular hypertension), which can progress to glaucoma if not monitored and managed; this requires regular intraocular pressure monitoring in patients on long-term topical steroids, with consideration of steroid-sparing alternatives or additional glaucoma treatment if pressure becomes significantly elevated.', 5),
('f7000000-0000-0000-0000-000000000036', 'A', 'Anterior uveitis, given the significant anterior chamber inflammation described', false, 'Ruled out because the scenario specifically describes episcleral/conjunctival involvement without significant anterior chamber inflammation, which is more consistent with episcleritis than anterior uveitis.', 1),
('f7000000-0000-0000-0000-000000000036', 'B', 'Retinal vasculitis', false, 'Ruled out because retinal vasculitis would show posterior segment/retinal vessel involvement on fundoscopy, not this pattern of episcleral/conjunctival involvement without significant anterior chamber inflammation.', 2),
('f7000000-0000-0000-0000-000000000036', 'C', 'Optic neuritis', false, 'Ruled out because optic neuritis involves the optic nerve, causing pain on eye movement and visual loss with a relative afferent pupillary defect, a different presentation from the episcleral/conjunctival findings described here.', 3),
('f7000000-0000-0000-0000-000000000036', 'D', 'Cataract, unrelated to any inflammatory process', false, 'Ruled out because cataract is a lens opacity causing gradual visual blurring, not an acute painful red eye with episcleral/conjunctival inflammation.', 4),
('f7000000-0000-0000-0000-000000000036', 'E', 'Episcleritis associated with inflammatory bowel disease activity', true, 'Correct. Episcleritis is a recognised extra-intestinal ocular manifestation of inflammatory bowel disease, often correlating with intestinal disease activity, distinguishing it from the less common but more serious IBD-associated anterior uveitis (which would show significant anterior chamber inflammation, not present here).', 5),
('f7000000-0000-0000-0000-000000000037', 'A', 'Simple episcleritis', false, 'Ruled out because episcleritis is a much milder, typically self-limiting condition without scleral thinning or perforation risk, a very different severity from the necrotising process described here.', 1),
('f7000000-0000-0000-0000-000000000037', 'B', 'Anterior uveitis alone', false, 'Ruled out because although uveitis can coexist, the specific finding of scleral thinning with visible underlying uvea reflects necrotising scleritis, a distinct and more severe process than uveitis alone.', 2),
('f7000000-0000-0000-0000-000000000037', 'C', 'Conjunctivitis', false, 'Ruled out because conjunctivitis does not cause scleral thinning or tissue necrosis; this represents a much more superficial, milder process than the necrotising scleritis described here.', 3),
('f7000000-0000-0000-0000-000000000037', 'D', 'Necrotising scleritis', true, 'Correct. Rapidly progressive, painful scleral thinning with visible underlying uvea (scleromalacia), in a patient with an ANCA-associated vasculitis (granulomatosis with polyangiitis), is characteristic of necrotising scleritis, the most severe form of scleritis, carrying a significant risk of scleral perforation and requiring urgent, aggressive systemic immunosuppressive treatment alongside ophthalmological management.', 4),
('f7000000-0000-0000-0000-000000000037', 'E', 'Corneal ulcer unrelated to scleral involvement', false, 'Ruled out because the specific findings described (scleral thinning, visible uvea) relate to the sclera, not primarily the cornea, pointing to necrotising scleritis.', 5),
('f7000000-0000-0000-0000-000000000038', 'A', 'Referral for rheumatological assessment to investigate for an underlying spondyloarthropathy, such as ankylosing spondylitis', true, 'Correct. HLA-B27-associated recurrent anterior uveitis is strongly linked to the seronegative spondyloarthropathies, particularly ankylosing spondylitis; given his back symptoms, referral for rheumatological assessment (potentially including imaging for sacroiliitis) is appropriate to investigate for an underlying, possibly previously undiagnosed, spondyloarthropathy.', 1),
('f7000000-0000-0000-0000-000000000038', 'B', 'No further assessment needed, as HLA-B27 positivity alone is sufficient for diagnosis of a specific condition', false, 'Ruled out because HLA-B27 positivity alone is not diagnostic of any specific condition; it needs to be interpreted alongside clinical assessment (such as rheumatological evaluation of his back symptoms) to determine whether an associated spondyloarthropathy is present.', 2),
('f7000000-0000-0000-0000-000000000038', 'C', 'Immediate spinal surgery without further assessment', false, 'Ruled out because this is a vastly disproportionate response to intermittent back stiffness; appropriate rheumatological assessment (history, examination, imaging) should precede any consideration of specific treatment, and surgery would rarely if ever be the appropriate initial approach for inflammatory back symptoms.', 3),
('f7000000-0000-0000-0000-000000000038', 'D', 'Treat the uveitis alone with no further investigation of systemic associations', false, 'Ruled out because recurrent HLA-B27-associated uveitis with concurrent back symptoms warrants investigation for an underlying systemic association, not treatment of the eye alone in isolation.', 4),
('f7000000-0000-0000-0000-000000000038', 'E', 'Reassure him that back stiffness is unrelated to his eye condition', false, 'Ruled out because there is a well-recognised association between HLA-B27-related uveitis and spondyloarthropathy, making it clinically relevant and appropriate to specifically investigate his back symptoms rather than dismissing a potential connection.', 5),
('f7000000-0000-0000-0000-000000000039', 'A', 'Vitreous haemorrhage alone', false, 'Ruled out because vitreous haemorrhage causes a hazy, red-tinged view without a discrete detached retinal appearance, a different pattern from the specific curtain field defect and grey elevated retina described here.', 1),
('f7000000-0000-0000-0000-000000000039', 'B', 'Rhegmatogenous retinal detachment', true, 'Correct. A curtain-like visual field defect, preceded by flashing lights (photopsia) and floaters, with a grey, elevated retina on fundoscopy, is characteristic of rhegmatogenous retinal detachment, caused by a retinal break allowing fluid to accumulate beneath the neurosensory retina; this is an ophthalmic emergency requiring urgent surgical assessment and repair to preserve vision, particularly if the macula is not yet involved.', 2),
('f7000000-0000-0000-0000-000000000039', 'C', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes a pale, ischaemic retina with a cherry-red spot, not this specific pattern of preceding photopsia/floaters with a curtain field defect and detached retinal appearance.', 3),
('f7000000-0000-0000-0000-000000000039', 'D', 'Migraine with aura', false, 'Ruled out because migrainous visual aura is transient and fully reversible, not this persistent curtain field defect with a confirmed structural finding (detached retina) on fundoscopy.', 4),
('f7000000-0000-0000-0000-000000000039', 'E', 'Simple posterior vitreous detachment without retinal detachment', false, 'Ruled out because although PVD can cause similar preceding symptoms (flashes, floaters) and is a common precursor, the presence of a curtain visual field defect with a grey, elevated retina confirms progression to an actual retinal detachment, not simple PVD alone.', 5),
('f7000000-0000-0000-0000-000000000040', 'A', 'Simple reassurance, as the outcome cannot be improved regardless of intervention', false, 'Ruled out because although visual prognosis in established CRAO is often poor, timely assessment and treatment (including thrombolysis where appropriate and within the time window) may offer some chance of improvement, and identification of the underlying cause remains important for secondary prevention regardless.', 1),
('f7000000-0000-0000-0000-000000000040', 'B', 'Routine outpatient ophthalmology referral within two weeks', false, 'Ruled out because CRAO is a time-critical emergency requiring immediate assessment, not delayed routine outpatient referral.', 2),
('f7000000-0000-0000-0000-000000000040', 'C', 'Urgent assessment as a stroke-equivalent emergency, including consideration of thrombolysis within the appropriate time window and investigation for an embolic source', true, 'Correct. Central retinal artery occlusion is considered an ophthalmic and systemic vascular emergency, equivalent to an acute stroke of the retina; urgent assessment should include consideration of thrombolysis if within the appropriate time window (per local protocols) and prompt investigation for an embolic source (here, atrial fibrillation is a strong candidate), alongside standard secondary stroke prevention measures.', 3),
('f7000000-0000-0000-0000-000000000040', 'D', 'Topical antibiotic eye drops as the primary treatment', false, 'Ruled out because CRAO is a vascular occlusive event, not an infective process; topical antibiotics have no role in its emergency management.', 4),
('f7000000-0000-0000-0000-000000000040', 'E', 'Discharge home with no further investigation, as the visual loss is likely permanent regardless of cause', false, 'Ruled out because identifying the underlying embolic source (here, likely his atrial fibrillation) is important for secondary prevention of future vascular events, including stroke, making further investigation essential regardless of the visual prognosis for this particular eye.', 5),
('f7000000-0000-0000-0000-000000000041', 'A', 'Dry age-related macular degeneration', false, $x$Ruled out because dry AMD is characterised by drusen and geographic atrophy without the subretinal fluid, haemorrhage, or neovascularisation seen in the wet form; this patient's findings (fluid, haemorrhage) indicate progression to wet AMD.$x$, 1),
('f7000000-0000-0000-0000-000000000041', 'B', 'Central serous retinopathy', false, $x$Ruled out because although CSR also causes subretinal fluid and metamorphopsia, it typically occurs in younger patients and is not associated with drusen and haemorrhage in this age-related pattern; this patient's presentation is more consistent with wet AMD.$x$, 2),
('f7000000-0000-0000-0000-000000000041', 'C', 'Wet (neovascular) age-related macular degeneration', true, 'Correct. Progressive central visual distortion (metamorphopsia) with drusen, subretinal fluid and haemorrhage at the macula is characteristic of wet (neovascular) age-related macular degeneration, caused by abnormal choroidal neovascularisation beneath the retina; this requires urgent referral for anti-VEGF treatment, as prompt treatment offers the best chance of preserving vision.', 3),
('f7000000-0000-0000-0000-000000000041', 'D', 'Diabetic macular oedema', false, 'Ruled out because there is no diabetes history given, and the specific combination of drusen with subretinal neovascular changes is characteristic of AMD, not diabetic disease.', 4),
('f7000000-0000-0000-0000-000000000041', 'E', 'Simple cataract', false, 'Ruled out because cataract causes generalised visual blurring from lens opacity, not this specific pattern of central distortion (metamorphopsia) with macular subretinal fluid and haemorrhage.', 5),
('f7000000-0000-0000-0000-000000000042', 'A', 'Simple conjunctival haemorrhage requiring no specific action', false, 'Ruled out because a subconjunctival haemorrhage is a different, generally benign finding (blood beneath the conjunctiva on the ocular surface), distinct from blood within the anterior chamber (hyphema), which carries more significant risks requiring active monitoring and management.', 1),
('f7000000-0000-0000-0000-000000000042', 'B', 'Retinal detachment', false, 'Ruled out because although trauma can also cause retinal detachment (which should be considered and excluded), the specific finding described (blood layering in the anterior chamber) is a hyphema, a distinct finding requiring its own specific assessment and monitoring.', 2),
('f7000000-0000-0000-0000-000000000042', 'C', 'Corneal abrasion alone', false, 'Ruled out because a corneal abrasion would show a defect on fluorescein staining of the cornea, not blood layering within the anterior chamber, which is the specific finding of hyphema described here.', 3),
('f7000000-0000-0000-0000-000000000042', 'D', 'No specific monitoring required beyond simple analgesia', false, 'Ruled out because traumatic hyphema carries significant risks (rebleeding, raised intraocular pressure, corneal blood staining) requiring active ophthalmological monitoring and management, not simply analgesia alone.', 4),
('f7000000-0000-0000-0000-000000000042', 'E', 'Traumatic hyphema, requiring urgent ophthalmological assessment and monitoring for rebleeding and raised intraocular pressure', true, 'Correct. Blood visibly layering in the anterior chamber following blunt trauma is a traumatic hyphema; urgent ophthalmological assessment is needed, with monitoring for the significant risks of rebleeding (which can occur in the following days and is often more severe than the initial bleed) and raised intraocular pressure, both of which can threaten vision if not appropriately managed.', 5),
('f7000000-0000-0000-0000-000000000043', 'A', 'Acute anterior uveitis', false, 'Ruled out because although uveitis also causes a painful red eye, it typically shows a constricted (not mid-dilated) pupil, and intraocular pressure is usually normal or low, not this markedly elevated pressure characteristic of angle closure.', 1),
('f7000000-0000-0000-0000-000000000043', 'B', 'Conjunctivitis', false, 'Ruled out because conjunctivitis does not cause this degree of pain, corneal haze, pupillary changes, or markedly raised intraocular pressure.', 2),
('f7000000-0000-0000-0000-000000000043', 'C', 'Corneal abrasion', false, 'Ruled out because a corneal abrasion would show a defect on fluorescein staining without this specific pattern of pupillary and pressure changes characteristic of angle closure.', 3),
('f7000000-0000-0000-0000-000000000043', 'D', 'Acute angle-closure glaucoma', true, 'Correct. Severe eye pain with redness, blurred vision, haloes around lights, a fixed mid-dilated pupil, corneal haze, and markedly elevated intraocular pressure together are characteristic of acute angle-closure glaucoma, an ophthalmic emergency caused by sudden obstruction of aqueous outflow at the anterior chamber angle, requiring urgent pressure-lowering treatment to prevent permanent optic nerve damage and vision loss.', 4),
('f7000000-0000-0000-0000-000000000043', 'E', 'Simple migraine with associated visual disturbance', false, 'Ruled out because migraine does not cause these specific objective ocular findings (fixed pupil, corneal haze, markedly raised intraocular pressure), which indicate a true ophthalmic emergency requiring immediate treatment.', 5),
('f7000000-0000-0000-0000-000000000044', 'A', 'Microbial keratitis', true, 'Correct. A painful red eye with photophobia, reduced vision, and a corneal infiltrate with an overlying fluorescein-staining epithelial defect, in a contact lens wearer (a major risk factor), is characteristic of microbial keratitis, an ophthalmic emergency requiring urgent corneal scraping for microbiological diagnosis and prompt initiation of intensive topical antimicrobial treatment to prevent corneal scarring and vision loss.', 1),
('f7000000-0000-0000-0000-000000000044', 'B', 'Simple allergic conjunctivitis', false, 'Ruled out because allergic conjunctivitis does not cause a corneal infiltrate or epithelial defect; these findings indicate a corneal, not simply conjunctival, process requiring urgent treatment.', 2),
('f7000000-0000-0000-0000-000000000044', 'C', 'Episcleritis', false, 'Ruled out because episcleritis causes mild, superficial episcleral inflammation without a corneal infiltrate or epithelial defect, a different and much milder condition than microbial keratitis.', 3),
('f7000000-0000-0000-0000-000000000044', 'D', 'Simple dry eye syndrome', false, 'Ruled out because dry eye typically causes milder, chronic irritation without an acute corneal infiltrate and staining epithelial defect as described here.', 4),
('f7000000-0000-0000-0000-000000000044', 'E', 'Acute angle-closure glaucoma', false, 'Ruled out because although this also causes a painful red eye, it presents with a fixed, mid-dilated pupil and markedly raised intraocular pressure, not a corneal infiltrate with a staining epithelial defect, which is specific to keratitis.', 5),
('f7000000-0000-0000-0000-000000000045', 'A', 'The patient should be immediately labelled as malingering without further assessment', false, 'Ruled out because prematurely assuming malingering without thorough assessment risks missing a genuine organic cause and can also unfairly stigmatise patients whose visual loss may reflect a genuine functional/non-organic disorder rather than deliberate deception.', 1),
('f7000000-0000-0000-0000-000000000045', 'B', 'A thorough assessment should still be conducted to exclude organic causes before considering a non-organic or functional explanation', true, 'Correct. Even when initial findings raise suspicion of a non-organic component, a thorough, careful assessment (including detailed history, examination, and appropriate investigations) must first be conducted to exclude genuine organic pathology, given that some organic causes of visual loss can present with a normal-appearing fundus (e.g. early or subtle optic nerve or higher visual pathway pathology); a diagnosis of non-organic visual loss should only be made after appropriately excluding organic disease, not assumed prematurely.', 2),
('f7000000-0000-0000-0000-000000000045', 'C', 'No further investigation is needed once a normal fundus examination is found', false, 'Ruled out because a normal fundus does not exclude all organic causes of visual loss (e.g. some optic nerve or higher visual pathway pathology can present with an initially normal-appearing fundus), so further assessment remains important.', 3),
('f7000000-0000-0000-0000-000000000045', 'D', 'The patient should be discharged immediately with no follow-up', false, 'Ruled out because thorough assessment and appropriate follow-up are needed regardless of whether an organic or non-organic cause is ultimately identified, given the significant impact of the reported visual loss.', 4),
('f7000000-0000-0000-0000-000000000045', 'E', 'Non-organic visual loss is always intentional and equivalent to malingering', false, 'Ruled out because non-organic (functional) visual loss can occur without conscious intent, distinct from malingering (which involves deliberate fabrication for a specific external gain); this distinction is clinically and ethically important.', 5),
('f7000000-0000-0000-0000-000000000046', 'A', 'A benign finding requiring no further assessment', false, 'Ruled out because although PVD itself is often benign, it carries a meaningful risk of an associated retinal tear, particularly in myopic patients, making urgent dilated examination important to exclude this treatable precursor to retinal detachment.', 1),
('f7000000-0000-0000-0000-000000000046', 'B', 'Definite retinal detachment requiring immediate surgery without further assessment', false, 'Ruled out because there is no curtain field defect described, meaning a full retinal detachment has not yet been confirmed; the priority is urgent fundoscopic assessment to determine whether a retinal tear (requiring prompt treatment to prevent progression to detachment) is present.', 2),
('f7000000-0000-0000-0000-000000000046', 'C', 'Posterior vitreous detachment, requiring urgent dilated fundoscopic examination to exclude an associated retinal tear or detachment', true, 'Correct. Sudden onset of floaters and flashes, without a curtain visual field defect, is characteristic of posterior vitreous detachment (the vitreous gel separating from the retina), a common age-related process, particularly in myopic patients; however, this requires urgent dilated fundoscopic examination to exclude an associated retinal tear, which can occur at the time of PVD and, if untreated, risks progressing to a full retinal detachment.', 3),
('f7000000-0000-0000-0000-000000000046', 'D', 'Simple migraine with visual aura', false, 'Ruled out because migrainous aura typically causes positive visual phenomena like zigzag lines lasting minutes, not this pattern of floaters and flashes associated with vitreous changes in a myopic patient, which is characteristic of PVD.', 4),
('f7000000-0000-0000-0000-000000000046', 'E', 'Cataract progression', false, 'Ruled out because cataract causes gradual visual blurring, not this acute onset of floaters and flashes characteristic of vitreoretinal traction/PVD.', 5),
('f7000000-0000-0000-0000-000000000047', 'A', 'A normal, expected fluctuation requiring no specific action', false, 'Ruled out because a sudden, significant worsening of vision with new distortion is a significant symptom requiring prompt reassessment, not simply an expected fluctuation to be disregarded.', 1),
('f7000000-0000-0000-0000-000000000047', 'B', 'Complete resolution of his underlying AMD requiring no further monitoring', false, 'Ruled out because worsening symptoms are the opposite of resolution; this presentation specifically suggests disease reactivation requiring urgent reassessment, not a sign that no further monitoring is needed.', 2),
('f7000000-0000-0000-0000-000000000047', 'C', 'Simple cataract progression unrelated to his AMD', false, 'Ruled out because cataract causes gradual, generalised visual blurring, not this specific pattern of acute worsening with new distortion in an eye with known wet AMD, which points to disease reactivation.', 3),
('f7000000-0000-0000-0000-000000000047', 'D', 'Reactivation of choroidal neovascularisation, potentially with subretinal haemorrhage, requiring urgent reassessment', true, 'Correct. Sudden worsening of central vision with new distortion in an eye with known wet AMD, even if previously treated, suggests reactivation of choroidal neovascularisation, potentially with subretinal haemorrhage; this requires urgent ophthalmological reassessment (including OCT imaging) to confirm reactivation and determine whether further anti-VEGF treatment is needed promptly.', 4),
('f7000000-0000-0000-0000-000000000047', 'E', 'A new, unrelated retinal detachment', false, 'Ruled out because although retinal detachment is a differential for acute visual change, the specific context of known wet AMD with new central distortion makes reactivation of the underlying neovascular process the most likely and directly relevant explanation, though this should still be properly assessed and confirmed.', 5),
('f7000000-0000-0000-0000-000000000048', 'A', 'Wet age-related macular degeneration', false, 'Ruled out because wet AMD typically occurs in older patients and is associated with drusen and neovascularisation, not this pattern in a young, otherwise healthy woman without these typical AMD-associated fundal changes.', 1),
('f7000000-0000-0000-0000-000000000048', 'B', 'Central serous retinopathy', true, 'Correct. Painless central visual blurring with a localised area of subretinal fluid at the macula on OCT, in a young to middle-aged adult, often associated with stress or corticosteroid use, is characteristic of central serous retinopathy, a condition causing fluid accumulation beneath the retina at the macula, which often resolves spontaneously over weeks to months, though can sometimes require treatment if persistent.', 2),
('f7000000-0000-0000-0000-000000000048', 'C', 'Diabetic macular oedema', false, 'Ruled out because there is no diabetes history given, and the clinical context (young patient, stress association) is more typical of central serous retinopathy.', 3),
('f7000000-0000-0000-0000-000000000048', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes a more extensive, progressive field defect (often described as a curtain), not this localised, subtle macular fluid accumulation described here.', 4),
('f7000000-0000-0000-0000-000000000048', 'E', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful visual loss with a relative afferent pupillary defect, not this painless presentation with localised subretinal macular fluid on OCT.', 5),
('f7000000-0000-0000-0000-000000000049', 'A', 'Urgent ophthalmology referral for assessment, given the risk of microbial keratitis even with relatively mild symptoms', true, 'Correct. A new corneal opacity in a contact lens wearer should be treated as potential microbial keratitis until proven otherwise, even with relatively mild symptoms, given the risk of rapid progression and permanent corneal scarring if untreated; urgent ophthalmology referral is needed for slit-lamp assessment and, if indicated, corneal scraping and treatment, rather than reassurance based on the absence of severe pain alone.', 1),
('f7000000-0000-0000-0000-000000000049', 'B', 'Reassurance and routine follow-up in several weeks, given the lack of significant pain', false, 'Ruled out because the absence of severe pain does not exclude significant corneal pathology requiring urgent assessment; a new corneal opacity in a contact lens wearer warrants urgent, not delayed, evaluation.', 2),
('f7000000-0000-0000-0000-000000000049', 'C', 'Simply stopping contact lens wear with no further action or referral', false, 'Ruled out because although stopping lens wear is appropriate, this alone is insufficient; urgent ophthalmological assessment is still needed to properly evaluate and, if necessary, treat the corneal finding.', 3),
('f7000000-0000-0000-0000-000000000049', 'D', 'Prescribing over-the-counter lubricating drops with no referral', false, 'Ruled out because lubricating drops do not address a potential infective corneal process, and this scenario requires urgent specialist assessment, not simple symptomatic treatment without referral.', 4),
('f7000000-0000-0000-0000-000000000049', 'E', 'No action needed, as painless corneal findings are never significant', false, 'Ruled out because corneal infiltrates, even when relatively painless, can represent significant, sight-threatening pathology (including early microbial keratitis) requiring prompt specialist assessment.', 5),
('f7000000-0000-0000-0000-000000000050', 'A', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes complete, not partial/sectoral, visual field loss affecting the whole eye, unlike this pattern limited to a specific field distribution corresponding to a branch vessel.', 1),
('f7000000-0000-0000-0000-000000000050', 'B', 'Retinal detachment', false, 'Ruled out because although retinal detachment can also cause a progressive field defect, the strong vascular risk factor context and typical presentation described here is more consistent with a vascular occlusive event (branch retinal artery occlusion).', 2),
('f7000000-0000-0000-0000-000000000050', 'C', 'Simple migraine with visual aura', false, 'Ruled out because migraine aura is transient and fully reversible, not this persistent visual field loss in a patient with significant vascular risk factors, which points to an ischaemic vascular cause.', 3),
('f7000000-0000-0000-0000-000000000050', 'D', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful, more central visual loss with a relative afferent pupillary defect, not this specific sectoral field loss pattern corresponding to a retinal vascular branch distribution.', 4),
('f7000000-0000-0000-0000-000000000050', 'E', 'Branch retinal artery occlusion from embolic or thrombotic occlusion of a retinal arterial branch', true, 'Correct. Sudden, painless visual field loss corresponding to the distribution of a specific retinal arterial branch, in a patient with vascular risk factors (hypertension, diabetes), is characteristic of branch retinal artery occlusion, sharing the same underlying embolic/thrombotic mechanisms as central retinal artery occlusion but affecting only the territory supplied by the occluded branch vessel, requiring similarly urgent assessment for an embolic source and vascular risk factor management.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f7000000-0000-0000-0000-000000000001', 'Microaneurysms are typically the earliest visible sign of diabetic retinopathy, reflecting focal capillary wall weakness.', 1),
('f7000000-0000-0000-0000-000000000001', 'The absence of neovascularisation is the key feature distinguishing background (non-proliferative) from proliferative diabetic retinopathy, an important distinction for grading severity and guiding management.', 2),
('f7000000-0000-0000-0000-000000000001', 'Regular screening (typically annual, or more frequent if retinopathy is present) allows early detection and monitoring of progression, informing when more active intervention may be needed.', 3),
('f7000000-0000-0000-0000-000000000002', 'Proliferative diabetic retinopathy, defined by neovascularisation, carries a significant risk of severe visual loss from vitreous haemorrhage or tractional retinal detachment if left untreated, justifying prompt treatment even without current symptoms.', 1),
('f7000000-0000-0000-0000-000000000002', 'Pan-retinal photocoagulation works by reducing the ischaemic retinal area driving VEGF-mediated neovascularisation, rather than directly treating the new vessels themselves.', 2),
('f7000000-0000-0000-0000-000000000002', 'Early treatment of proliferative retinopathy, before complications develop, offers the best chance of preserving vision, reinforcing the importance of regular screening to detect this stage promptly.', 3),
('f7000000-0000-0000-0000-000000000003', 'Diabetic macular oedema specifically affects central vision (unlike peripheral retinopathy changes, which may be asymptomatic), making it a priority for prompt, targeted treatment.', 1),
('f7000000-0000-0000-0000-000000000003', 'Intravitreal anti-VEGF therapy has become first-line for diabetic macular oedema, working by directly reducing the vascular permeability driving fluid accumulation in the macula.', 2),
('f7000000-0000-0000-0000-000000000003', 'OCT provides objective, quantitative assessment of macular thickness/fluid, useful both for confirming the diagnosis and for monitoring treatment response over subsequent visits.', 3),
('f7000000-0000-0000-0000-000000000004', $x$This 'early worsening' phenomenon is a well-documented finding in clinical trials of rapid glycaemic optimisation, particularly relevant when improving control quickly in patients with pre-existing significant retinopathy.$x$, 1),
('f7000000-0000-0000-0000-000000000004', 'Close ophthalmological monitoring is recommended for patients with pre-existing retinopathy undergoing rapid glycaemic improvement, given this recognised transient risk period.', 2),
('f7000000-0000-0000-0000-000000000004', 'Despite this transient early worsening, the long-term benefit of good glycaemic control in reducing overall diabetic retinopathy progression risk remains well-established, so intensive control should generally be pursued (with appropriate monitoring) rather than avoided.', 3),
('f7000000-0000-0000-0000-000000000005', 'A hazy, red-tinged view obscuring normal retinal detail on fundoscopy is a characteristic finding of vitreous haemorrhage, reflecting blood within the vitreous cavity.', 1),
('f7000000-0000-0000-0000-000000000005', 'Known proliferative diabetic retinopathy (with fragile neovascular vessels prone to bleeding) is the key risk factor and contextual clue pointing to this diagnosis in a diabetic patient with sudden visual loss.', 2),
('f7000000-0000-0000-0000-000000000005', 'Urgent ophthalmological assessment (including ultrasound if the view is too hazy for direct visualisation) is needed to assess the extent of haemorrhage and exclude an associated retinal detachment, guiding further management.', 3),
('f7000000-0000-0000-0000-000000000006', 'Annual screening is the standard interval for patients without significant retinopathy, balancing early detection against screening burden and resource use.', 1),
('f7000000-0000-0000-0000-000000000006', 'Diabetic retinopathy is frequently asymptomatic in earlier, treatable stages, making structured, regular screening (rather than waiting for symptoms) essential to detect and treat disease before significant visual loss occurs.', 2),
('f7000000-0000-0000-0000-000000000006', 'Screening frequency can be individualised (increased) based on identified retinopathy severity, reflecting a risk-stratified approach within the overall screening programme.', 3),
('f7000000-0000-0000-0000-000000000007', 'Venous beading and cotton wool spots reflect more significant retinal ischaemia than the microaneurysms and haemorrhages of mild background retinopathy, marking the pre-proliferative (severe non-proliferative) stage.', 1),
('f7000000-0000-0000-0000-000000000007', 'This stage carries a significantly increased risk of progression to proliferative retinopathy within the following year, justifying closer monitoring intervals than for mild background disease.', 2),
('f7000000-0000-0000-0000-000000000007', 'Recognising this grading distinction is important for appropriately risk-stratifying screening intervals and considering when closer specialist ophthalmology input may be warranted, even before neovascularisation (proliferative disease) develops.', 3),
('f7000000-0000-0000-0000-000000000008', 'Pregnancy-related hormonal and haemodynamic changes are thought to contribute to accelerated retinopathy progression risk, distinct from the retinopathy risk related to glycaemic control alone.', 1),
('f7000000-0000-0000-0000-000000000008', 'Increased screening frequency during pregnancy (and sometimes preconception counselling with baseline assessment before pregnancy) allows early detection and management of any progression.', 2),
('f7000000-0000-0000-0000-000000000008', 'This heightened risk period typically extends through pregnancy and into the early postpartum period, informing the overall screening schedule around this time.', 3),
('f7000000-0000-0000-0000-000000000009', 'Rubeosis iridis (new vessel growth on the iris) is a specific, important sign that retinal ischaemia has become severe enough to drive neovascularisation beyond the retina itself, into the anterior segment of the eye.', 1),
('f7000000-0000-0000-0000-000000000009', 'Neovascular glaucoma results from these new vessels and associated fibrous tissue obstructing the trabecular meshwork/anterior chamber angle, impairing aqueous outflow and raising intraocular pressure.', 2),
('f7000000-0000-0000-0000-000000000009', 'This is a serious, sight-threatening complication requiring urgent ophthalmological management, often including further pan-retinal photocoagulation (to reduce the ischaemic drive), anti-VEGF therapy, and specific glaucoma treatment to control intraocular pressure.', 3),
('f7000000-0000-0000-0000-000000000010', 'Type 2 diabetes is often preceded by a prolonged period of undiagnosed hyperglycaemia, meaning some patients may already have developed diabetic retinopathy by the time of formal diagnosis, justifying prompt screening at diagnosis.', 1),
('f7000000-0000-0000-0000-000000000010', 'This contrasts with type 1 diabetes, where the more acute, symptomatic onset typically means retinopathy has not yet developed at diagnosis, allowing screening to reasonably begin some years later (though local protocols vary).', 2),
('f7000000-0000-0000-0000-000000000010', 'Prompt baseline screening at type 2 diabetes diagnosis establishes a reference point for future comparison and ensures any pre-existing retinopathy is identified and appropriately managed from the outset.', 3),
('f7000000-0000-0000-0000-000000000011', 'VEGF is upregulated in response to retinal ischaemia (a key driver in diabetic eye disease) and increases vascular permeability, directly contributing to macular oedema formation.', 1),
('f7000000-0000-0000-0000-000000000011', 'By blocking VEGF, anti-VEGF therapy addresses the underlying pathophysiological driver of fluid leakage, rather than simply treating the fluid accumulation symptomatically.', 2),
('f7000000-0000-0000-0000-000000000011', 'Regular, repeated intravitreal injections are typically required, as the effect of each dose is time-limited, reflecting the ongoing nature of the underlying diabetic vascular pathology.', 3),
('f7000000-0000-0000-0000-000000000012', 'Contraction of fibrovascular tissue associated with retinal neovascularisation creates traction on the retina, distinguishing tractional detachment mechanistically from rhegmatogenous detachment (caused by a retinal break allowing fluid to accumulate beneath the retina).', 1),
('f7000000-0000-0000-0000-000000000012', 'A relatively clear vitreous with a distinct, often concave or dome-shaped elevated retinal appearance helps distinguish tractional detachment from vitreous haemorrhage, though both can coexist in advanced proliferative disease.', 2),
('f7000000-0000-0000-0000-000000000012', 'Tractional retinal detachment, particularly if threatening or involving the macula, requires urgent vitreoretinal surgical assessment, as it represents a sight-threatening complication of advanced proliferative diabetic retinopathy.', 3),
('f7000000-0000-0000-0000-000000000013', 'Sudden, painless, profound visual loss is characteristic of a vascular retinal event, distinguishing it from the more gradual visual change of many other eye conditions.', 1),
('f7000000-0000-0000-0000-000000000013', 'The cherry-red spot at the macula is a classic, specific sign of CRAO, reflecting relative preservation of the thin foveal retina (allowing visualisation of underlying choroidal circulation) against the surrounding pale, ischaemic, oedematous retina.', 2),
('f7000000-0000-0000-0000-000000000013', 'CRAO is considered an ophthalmic and systemic vascular emergency, similar to stroke, requiring urgent assessment for underlying embolic or other vascular causes and consideration of time-critical treatment options.', 3),
('f7000000-0000-0000-0000-000000000014', $x$The 'blood and thunder' fundal appearance -- widespread haemorrhages, venous dilation/tortuosity, and disc swelling -- is a classic, specific sign of central retinal vein occlusion.$x$, 1),
('f7000000-0000-0000-0000-000000000014', 'Risk factors for CRVO overlap with general cardiovascular risk factors (hypertension, diabetes, hyperlipidaemia) as well as raised intraocular pressure/glaucoma, informing the relevant systemic workup.', 2),
('f7000000-0000-0000-0000-000000000014', 'Complications of CRVO include macular oedema (requiring anti-VEGF treatment) and, in ischaemic cases, subsequent neovascularisation and neovascular glaucoma, similar to the ischaemic complications seen in advanced diabetic eye disease.', 3),
('f7000000-0000-0000-0000-000000000015', $x$The classic description of transient visual loss as a 'curtain coming down' (or going up as it resolves) reflects the pattern of retinal ischaemia and subsequent reperfusion in amaurosis fugax.$x$, 1),
('f7000000-0000-0000-0000-000000000015', 'Complete resolution within minutes distinguishes amaurosis fugax from a completed retinal vascular occlusion (e.g. CRAO), where visual loss is typically persistent.', 2),
('f7000000-0000-0000-0000-000000000015', 'Amaurosis fugax represents a TIA equivalent affecting the retinal circulation and should prompt the same urgent vascular risk assessment and secondary prevention measures (carotid imaging, antiplatelet therapy, risk factor modification) as a cerebral TIA, given the shared underlying embolic mechanism and stroke risk.', 3),
('f7000000-0000-0000-0000-000000000016', 'Jaw claudication and scalp tenderness are highly specific systemic symptoms for giant cell arteritis, distinguishing it from other causes of sudden visual loss in older patients.', 1),
('f7000000-0000-0000-0000-000000000016', 'A markedly raised ESR/CRP supports the diagnosis of GCA, though treatment should not be delayed for biopsy confirmation given the urgency of preventing further visual loss.', 2),
('f7000000-0000-0000-0000-000000000016', 'Immediate high-dose corticosteroid treatment, started on clinical suspicion, is critical to reduce the significant risk of subsequent visual loss in the unaffected eye, making this one of the true ophthalmic emergencies requiring same-day recognition and treatment.', 3),
('f7000000-0000-0000-0000-000000000017', 'The parasympathetic fibres controlling pupillary constriction run on the outer surface of the third cranial nerve, making them particularly vulnerable to external compression (e.g. from an aneurysm), which classically causes early pupillary involvement.', 1),
('f7000000-0000-0000-0000-000000000017', 'In contrast, microvascular causes of third nerve palsy (e.g. from diabetes or hypertension) typically affect the more centrally located fibres supplying the extraocular muscles first, often sparing the pupil, at least initially.', 2),
('f7000000-0000-0000-0000-000000000017', 'This distinction (pupil-involving versus pupil-sparing) is a critical, classic clinical teaching point guiding urgency of investigation, as pupil involvement mandates urgent exclusion of a compressive, potentially life-threatening aneurysmal cause.', 3),
('f7000000-0000-0000-0000-000000000018', 'Pupil-sparing (rather than pupil-involving) third nerve palsy suggests a microvascular, rather than compressive, cause, reflecting the pattern of nerve fibre involvement in ischaemic versus compressive injury.', 1),
('f7000000-0000-0000-0000-000000000018', 'Diabetes (and hypertension) are classic risk factors for microvascular cranial mononeuropathies, including third, fourth and sixth nerve palsies.', 2),
('f7000000-0000-0000-0000-000000000018', 'Microvascular third nerve palsy typically resolves spontaneously over weeks to months, though careful initial assessment (to confirm pupil sparing and exclude any atypical features) remains important before attributing the palsy to a benign microvascular cause.', 3),
('f7000000-0000-0000-0000-000000000019', 'Failure of adduction of one eye with nystagmus of the contralateral abducting eye on lateral gaze is a highly specific sign localising to the medial longitudinal fasciculus.', 1),
('f7000000-0000-0000-0000-000000000019', 'Preserved convergence, despite impaired adduction on lateral gaze, distinguishes an INO (an internuclear tract lesion) from a true third nerve palsy (which would impair convergence too).', 2),
('f7000000-0000-0000-0000-000000000019', 'Internuclear ophthalmoplegia, especially if bilateral, is highly suggestive of multiple sclerosis in a young patient, though it can also occur from brainstem stroke in older patients.', 3),
('f7000000-0000-0000-0000-000000000020', 'Papilloedema results from raised intracranial pressure transmitted along the optic nerve sheath, causing optic disc swelling visible on fundoscopy.', 1),
('f7000000-0000-0000-0000-000000000020', 'Chronic, untreated papilloedema can cause progressive optic nerve damage and visual field loss, which can become permanent if the underlying raised pressure is not adequately controlled.', 2),
('f7000000-0000-0000-0000-000000000020', 'Regular visual field testing is an important monitoring tool in patients with papilloedema/IIH, both to assess current visual impact and to guide the intensity of treatment needed (e.g. weight loss, medical therapy, or in severe/refractory cases, surgical intervention) to protect vision.', 3),
('f7000000-0000-0000-0000-000000000021', 'Homonymous visual field defects (same side loss in both eyes) always localise to a lesion posterior to the optic chiasm, on the side opposite the visual field loss, reflecting the point at which nasal retinal fibres have already crossed.', 1),
('f7000000-0000-0000-0000-000000000021', 'This differs from bitemporal hemianopia (chiasmal lesions) and monocular visual loss (pre-chiasmal, optic nerve lesions), together forming a classic neuro-ophthalmological localisation framework based on visual field pattern.', 2),
('f7000000-0000-0000-0000-000000000021', 'The specific post-chiasmal site (optic tract, radiations, or occipital cortex) can sometimes be further inferred from additional features (e.g. macular sparing suggesting occipital cortex involvement with dual blood supply), though the general localising principle (contralateral, post-chiasmal) applies broadly.', 3),
('f7000000-0000-0000-0000-000000000022', $x$The classic triad of ptosis (partial, from loss of sympathetic innervation to Muller's muscle), miosis, and anhidrosis defines Horner syndrome, reflecting sympathetic pathway disruption.$x$, 1),
('f7000000-0000-0000-0000-000000000022', 'The sympathetic pathway to the eye has a long course from the hypothalamus through the brainstem, spinal cord, sympathetic chain in the neck/chest, and along the carotid artery, meaning Horner syndrome can result from lesions at many different levels, including brachial plexus/sympathetic chain injury as described here.', 2),
('f7000000-0000-0000-0000-000000000022', 'Identifying the specific underlying cause (here, related to birth-associated brachial plexus and sympathetic chain trauma) is important, as Horner syndrome can also result from other causes (e.g. carotid dissection, apical lung tumour/Pancoast tumour) requiring different specific investigation and management.', 3),
('f7000000-0000-0000-0000-000000000023', 'An altitudinal (typically superior or inferior, rather than complete) visual field defect is a classic pattern for anterior ischaemic optic neuropathy, reflecting the segmental blood supply to the optic nerve head.', 1),
('f7000000-0000-0000-0000-000000000023', 'Distinguishing non-arteritic from arteritic (GCA-related) AION is critical, as the arteritic form requires immediate high-dose corticosteroid treatment to prevent fellow-eye involvement, while the non-arteritic form does not have the same urgent steroid indication, though underlying vascular risk factors should still be assessed and managed.', 2),
('f7000000-0000-0000-0000-000000000023', $x$Non-arteritic AION is associated with vascular risk factors (hypertension, diabetes, hyperlipidaemia) and anatomical predisposition (a small, crowded 'disc at risk' in the unaffected eye), distinguishing its risk profile and management approach from the arteritic form.$x$, 3),
('f7000000-0000-0000-0000-000000000024', 'Pain on eye movement accompanying visual loss is a classic feature of optic neuritis, reflecting inflammation of the optic nerve within its dural sheath.', 1),
('f7000000-0000-0000-0000-000000000024', 'A relative afferent pupillary defect (Marcus Gunn pupil) indicates a lesion of the optic nerve (afferent visual pathway) on the affected side.', 2),
('f7000000-0000-0000-0000-000000000024', 'MRI evidence of a demyelinating lesion, particularly with additional brain lesions, raises the likelihood of an underlying diagnosis of multiple sclerosis, informing further counselling and follow-up.', 3),
('f7000000-0000-0000-0000-000000000025', 'The cavernous sinus is a key anatomical location where multiple relevant cranial nerves (III, IV, VI, and the ophthalmic/maxillary divisions of V) run in close proximity, explaining why lesions here characteristically cause combinations of ophthalmoplegia and facial sensory loss.', 1),
('f7000000-0000-0000-0000-000000000025', 'Recognising this pattern of multiple, anatomically clustered cranial nerve involvement helps localise the lesion precisely, guiding urgent, targeted imaging (MRI with attention to the cavernous sinus) to identify the underlying cause.', 2),
('f7000000-0000-0000-0000-000000000025', 'Causes of cavernous sinus syndrome are diverse (thrombosis, aneurysm, tumour, infection/mucormycosis in immunocompromised patients), each requiring different specific management, making accurate localisation and urgent further investigation essential.', 3),
('f7000000-0000-0000-0000-000000000026', 'Acute anterior uveitis is a well-recognised extra-articular manifestation occurring in a significant proportion of patients with ankylosing spondylitis and other HLA-B27-associated spondyloarthropathies.', 1),
('f7000000-0000-0000-0000-000000000026', 'An irregular pupil from posterior synechiae (adhesions between the iris and lens) and ciliary flush are classic examination findings distinguishing uveitis from simpler causes of red eye.', 2),
('f7000000-0000-0000-0000-000000000026', 'Prompt ophthalmology referral and treatment (typically topical corticosteroids and mydriatics) are important to prevent complications such as glaucoma or cataract from recurrent or untreated episodes.', 3),
('f7000000-0000-0000-0000-000000000027', 'Posterior uveitis affects the choroid and/or retina (and often the vitreous), causing floaters and gradual visual blurring, distinct from the more acutely painful, photophobic presentation typical of anterior uveitis.', 1),
('f7000000-0000-0000-0000-000000000027', 'Sarcoidosis is a recognised systemic cause of uveitis, which can affect the anterior, posterior, or both segments of the eye, making it an important condition to consider and screen for in patients presenting with uveitis of unclear cause.', 2),
('f7000000-0000-0000-0000-000000000027', 'Perivascular sheathing (inflammatory cuffing around retinal vessels) is a characteristic fundoscopic finding in sarcoid-related posterior uveitis/retinal vasculitis.', 3),
('f7000000-0000-0000-0000-000000000028', 'The characteristically asymptomatic nature of JIA-associated uveitis, particularly in the oligoarticular ANA-positive subtype and in young children, is the key reason structured, regular screening (rather than symptom-triggered assessment) is recommended.', 1),
('f7000000-0000-0000-0000-000000000028', 'Untreated, chronic anterior uveitis in this population can lead to significant complications (cataract, glaucoma, band keratopathy, synechiae) that can threaten vision if not detected and treated early.', 2),
('f7000000-0000-0000-0000-000000000028', 'Screening frequency is typically risk-stratified based on JIA subtype, age at onset, and antibody status (e.g. ANA positivity), reflecting varying levels of uveitis risk across different JIA presentations.', 3),
('f7000000-0000-0000-0000-000000000029', 'Severe, deep, boring pain, often disturbing sleep, is a distinguishing feature of scleritis compared with the milder discomfort of episcleritis.', 1),
('f7000000-0000-0000-0000-000000000029', 'Scleritis is strongly associated with underlying systemic autoimmune conditions (rheumatoid arthritis, granulomatosis with polyangiitis, and others), making systemic assessment and, often, systemic immunosuppressive treatment (rather than topical treatment alone) important.', 2),
('f7000000-0000-0000-0000-000000000029', 'Scleritis carries a risk of serious complications (including scleral thinning/perforation and vision loss) if not promptly and adequately treated, distinguishing its urgency and management approach from the generally more benign, self-limiting episcleritis.', 3),
('f7000000-0000-0000-0000-000000000030', 'The phenylephrine blanching test is a useful clinical tool distinguishing episcleritis (superficial vessels blanch) from scleritis (deeper vessels do not blanch), helping guide the urgency and type of further management.', 1),
('f7000000-0000-0000-0000-000000000030', 'Episcleritis is generally a mild, often self-limiting condition, in contrast to the more severe, potentially sight-threatening nature of scleritis, reflecting the different depth and severity of inflammation involved.', 2),
('f7000000-0000-0000-0000-000000000030', 'Episcleritis can be idiopathic or associated with systemic conditions, but generally requires only symptomatic treatment (lubricants, sometimes topical NSAIDs), unlike scleritis, which often requires more intensive, sometimes systemic, treatment.', 3),
('f7000000-0000-0000-0000-000000000031', 'A hypopyon reflects a particularly severe degree of anterior chamber inflammation, with enough white cells accumulating to form a visible, settled layer, distinguishing it from milder anterior chamber cellular reactions.', 1),
('f7000000-0000-0000-0000-000000000031', $x$Behcet's disease is classically associated with recurrent, often severe uveitis, sometimes with hypopyon formation, alongside its other characteristic features (oral and genital ulcers, skin lesions).$x$, 2),
('f7000000-0000-0000-0000-000000000031', $x$Recurrent severe ocular Behcet's disease carries a significant risk of cumulative visual damage over time, often requiring systemic immunosuppressive treatment (beyond topical therapy alone) to adequately control inflammation and protect vision.$x$, 3),
('f7000000-0000-0000-0000-000000000032', 'The classic triad of conjunctivitis/uveitis, urethritis and arthritis (historically termed Reiter syndrome) occurring after a genitourinary or gastrointestinal infection defines reactive arthritis.', 1),
('f7000000-0000-0000-0000-000000000032', $x$Eye involvement in reactive arthritis can range from mild conjunctivitis to more significant anterior uveitis, both falling within the spectrum of this condition's ocular manifestations.$x$, 2),
('f7000000-0000-0000-0000-000000000032', 'Recognising this systemic syndrome, rather than treating the eye findings in isolation, is important for appropriate overall management and consideration of the underlying reactive arthritis diagnosis.', 3),
('f7000000-0000-0000-0000-000000000033', 'Sympathetic ophthalmia specifically affects the previously uninvolved (sympathising) eye following surgery or trauma to the other (exciting) eye, an important and distinguishing temporal/anatomical pattern.', 1),
('f7000000-0000-0000-0000-000000000033', 'The underlying mechanism is thought to involve an autoimmune response against ocular antigens exposed during the inciting surgery or trauma, which then cross-reacts with similar antigens in the fellow eye.', 2),
('f7000000-0000-0000-0000-000000000033', 'Although rare, this is a serious, potentially bilaterally blinding condition requiring prompt recognition and aggressive immunosuppressive treatment, making awareness of this possibility important after any significant ocular surgery or penetrating trauma.', 3),
('f7000000-0000-0000-0000-000000000034', $x$The pathergy test is a specific, supportive clinical sign for Behcet's disease, reflecting the condition's characteristic pattern of exaggerated inflammatory/pustular skin responses to minor trauma.$x$, 1),
('f7000000-0000-0000-0000-000000000034', $x$Behcet's disease diagnosis is based on a clinical criteria set combining recurrent oral ulceration with other features (genital ulcers, eye lesions, skin lesions, and a positive pathergy test), given the absence of a single definitive diagnostic laboratory test.$x$, 2),
('f7000000-0000-0000-0000-000000000034', $x$Recognising the combination of mucocutaneous, ocular and pathergy findings supports a confident clinical diagnosis of Behcet's disease, guiding appropriate systemic treatment given the condition's potential for significant morbidity, including vision loss from recurrent uveitis.$x$, 3),
('f7000000-0000-0000-0000-000000000035', 'Long-term topical corticosteroid use is a well-recognised cause of raised intraocular pressure, related to effects on aqueous outflow through the trabecular meshwork, distinguishing it as a specific, monitorable treatment-related risk.', 1),
('f7000000-0000-0000-0000-000000000035', 'Regular intraocular pressure monitoring is an essential part of managing patients on long-term topical corticosteroids for chronic uveitis, alongside monitoring for other steroid-related complications such as cataract.', 2),
('f7000000-0000-0000-0000-000000000035', 'Management of steroid-induced ocular hypertension may involve additional glaucoma treatment, or consideration of steroid-sparing immunosuppressive alternatives for the underlying uveitis, reflecting the need to balance inflammation control against treatment-related risk.', 3),
('f7000000-0000-0000-0000-000000000036', 'Episcleritis is one of several recognised extra-intestinal manifestations of inflammatory bowel disease, alongside others such as anterior uveitis, and often (though not invariably) correlates with intestinal disease activity.', 1),
('f7000000-0000-0000-0000-000000000036', 'Distinguishing episcleritis from the less common but potentially more serious IBD-associated anterior uveitis is important, based on the presence or absence of significant anterior chamber inflammation on slit-lamp examination.', 2),
('f7000000-0000-0000-0000-000000000036', 'Recognising ocular extra-intestinal manifestations can sometimes reflect or coincide with a flare of the underlying bowel disease, informing overall clinical assessment and management coordination between gastroenterology and ophthalmology.', 3),
('f7000000-0000-0000-0000-000000000037', 'Necrotising scleritis represents the most severe end of the scleritis spectrum, with scleral thinning risking perforation and permanent visual loss if not urgently and aggressively treated.', 1),
('f7000000-0000-0000-0000-000000000037', 'Strong associations with systemic vasculitides (particularly granulomatosis with polyangiitis) and other severe autoimmune conditions make systemic assessment and treatment essential, not just local ophthalmological management.', 2),
('f7000000-0000-0000-0000-000000000037', 'Urgent, often aggressive systemic immunosuppressive treatment is required, reflecting both the severity of the eye disease itself and the likely activity of the underlying systemic vasculitis.', 3),
('f7000000-0000-0000-0000-000000000038', 'HLA-B27 positivity in the context of recurrent anterior uveitis significantly raises the likelihood of an associated seronegative spondyloarthropathy, particularly ankylosing spondylitis.', 1),
('f7000000-0000-0000-0000-000000000038', 'Uveitis can sometimes be the presenting feature that leads to diagnosis of a previously unrecognised spondyloarthropathy, making appropriate systemic assessment important when uveitis and relevant symptoms (such as inflammatory back pain) coexist.', 2),
('f7000000-0000-0000-0000-000000000038', 'A coordinated approach between ophthalmology and rheumatology helps ensure both the eye disease and any underlying systemic condition are appropriately identified and managed together.', 3),
('f7000000-0000-0000-0000-000000000039', 'Photopsia (flashing lights) and floaters preceding visual field loss reflect vitreoretinal traction and, often, the retinal break itself, a classic prodromal symptom pattern for retinal detachment.', 1),
('f7000000-0000-0000-0000-000000000039', 'A curtain or shadow descending across the visual field reflects the specific area of retina that has detached, correlating anatomically with the position of the detachment.', 2),
('f7000000-0000-0000-0000-000000000039', 'Urgent surgical repair is time-critical, particularly to prevent or address macular involvement, as visual outcomes are significantly better when the macula remains attached (or is promptly reattached) compared with when macular detachment has already occurred.', 3),
('f7000000-0000-0000-0000-000000000040', $x$CRAO is treated with the same urgency as an acute ischaemic stroke, reflecting the retina's origin as an extension of the central nervous system and the shared underlying vascular/embolic mechanisms.$x$, 1),
('f7000000-0000-0000-0000-000000000040', 'Identifying and addressing the underlying embolic source (here, atrial fibrillation) is important not only for potential ocular outcome but critically for reducing the risk of a subsequent, potentially more devastating cerebral stroke.', 2),
('f7000000-0000-0000-0000-000000000040', 'The time window for potential intervention (e.g. thrombolysis) in CRAO is narrow, reinforcing the need for immediate emergency assessment rather than any delay in presentation or referral.', 3),
('f7000000-0000-0000-0000-000000000041', 'Metamorphopsia (visual distortion, straight lines appearing wavy) is a characteristic symptom of macular pathology, particularly associated with subretinal fluid displacing the normally flat retinal contour.', 1),
('f7000000-0000-0000-0000-000000000041', 'The presence of subretinal fluid and haemorrhage, rather than drusen and atrophy alone, distinguishes wet (neovascular) AMD from the more slowly progressive dry form.', 2),
('f7000000-0000-0000-0000-000000000041', 'Prompt referral and treatment with anti-VEGF therapy for wet AMD is time-critical, as delayed treatment is associated with worse visual outcomes, given the progressive nature of the neovascular process if untreated.', 3),
('f7000000-0000-0000-0000-000000000042', 'Traumatic hyphema results from disruption of iris or ciliary body blood vessels following blunt trauma, with blood settling in the anterior chamber under gravity.', 1),
('f7000000-0000-0000-0000-000000000042', 'The risk of rebleeding, typically in the days following the initial injury, is a critical concern, as a rebleed is often more severe than the original hyphema and carries a higher risk of complications.', 2),
('f7000000-0000-0000-0000-000000000042', 'Raised intraocular pressure is a recognised complication of hyphema (from blood obstructing the trabecular meshwork), requiring regular monitoring alongside assessment for other associated globe injuries.', 3),
('f7000000-0000-0000-0000-000000000043', 'The combination of severe pain, haloes around lights, a fixed mid-dilated pupil and markedly raised intraocular pressure is the classic presentation of acute angle-closure glaucoma, distinguishing it from other causes of red eye.', 1),
('f7000000-0000-0000-0000-000000000043', 'Corneal haze/oedema results from the acutely and severely raised intraocular pressure affecting corneal clarity, contributing to the visual blurring and haloes described.', 2),
('f7000000-0000-0000-0000-000000000043', 'Urgent pressure-lowering treatment (topical and systemic medications, followed by definitive laser iridotomy) is required emergently to prevent permanent optic nerve damage from the acutely elevated pressure.', 3),
('f7000000-0000-0000-0000-000000000044', 'Contact lens wear is a major risk factor for microbial keratitis, related to factors including corneal hypoxia, minor trauma, and biofilm formation on lenses/cases.', 1),
('f7000000-0000-0000-0000-000000000044', 'A corneal infiltrate with an overlying staining epithelial defect indicates active corneal infection/inflammation, distinguishing this from more superficial or milder ocular surface conditions.', 2),
('f7000000-0000-0000-0000-000000000044', 'Urgent corneal scraping for microbiological culture (to guide targeted antimicrobial therapy) alongside prompt initiation of intensive empirical topical treatment is essential, given the risk of rapid corneal destruction and permanent scarring if treatment is delayed or inadequate.', 3),
('f7000000-0000-0000-0000-000000000045', 'A normal-appearing fundus does not exclude all organic causes of visual loss, as some causes (early optic nerve or higher visual pathway pathology) can present with a normal fundus examination, requiring further assessment before considering a non-organic diagnosis.', 1),
('f7000000-0000-0000-0000-000000000045', 'Various specific clinical tests exist to help assess the consistency and plausibility of reported visual loss, aiding (though not always definitively proving) the distinction between organic and non-organic presentations.', 2),
('f7000000-0000-0000-0000-000000000045', 'Non-organic visual loss and malingering are distinct concepts, with non-organic (functional) visual loss potentially occurring without conscious intent, an important distinction for appropriate, non-judgemental patient management.', 3),
('f7000000-0000-0000-0000-000000000046', 'High myopia is a recognised risk factor for both posterior vitreous detachment and associated retinal tears/detachment, related to the altered vitreoretinal anatomy in elongated myopic eyes.', 1),
('f7000000-0000-0000-0000-000000000046', 'New-onset floaters and flashes, even without a curtain field defect, warrant urgent dilated fundoscopic examination specifically to look for a retinal tear, as prompt treatment (e.g. laser retinopexy) of a tear can prevent progression to full retinal detachment.', 2),
('f7000000-0000-0000-0000-000000000046', 'This proactive assessment approach reflects the principle that early intervention at the retinal tear stage offers a much better opportunity to prevent vision-threatening detachment than waiting for symptoms of established detachment to develop.', 3),
('f7000000-0000-0000-0000-000000000047', 'Wet AMD, even when previously treated, can reactivate, requiring ongoing monitoring and re-treatment with anti-VEGF therapy as needed, reflecting the chronic, relapsing nature of the underlying neovascular process.', 1),
('f7000000-0000-0000-0000-000000000047', 'New metamorphopsia (distortion) or acute visual worsening in a patient with known AMD should prompt urgent reassessment rather than being attributed to normal fluctuation, given the time-sensitive nature of effective retreatment.', 2),
('f7000000-0000-0000-0000-000000000047', 'OCT imaging is a key tool for confirming disease reactivation (detecting new fluid) and guiding retreatment decisions in the ongoing management of wet AMD.', 3),
('f7000000-0000-0000-0000-000000000048', 'Central serous retinopathy classically affects younger to middle-aged adults, often men, though it can occur in women too, distinguishing its typical demographic from the older population usually affected by AMD.', 1),
('f7000000-0000-0000-0000-000000000048', 'Associations with psychological stress and corticosteroid use (endogenous or exogenous) are well-recognised triggers/risk factors for central serous retinopathy.', 2),
('f7000000-0000-0000-0000-000000000048', 'Many cases resolve spontaneously over weeks to months, though persistent or recurrent cases may require specific treatment (e.g. laser or other targeted therapy), guiding an initial period of observation in straightforward cases before considering intervention.', 3),
('f7000000-0000-0000-0000-000000000049', 'Contact lens wear is a major risk factor for microbial keratitis, and any new corneal opacity in a lens wearer should prompt urgent assessment, regardless of symptom severity.', 1),
('f7000000-0000-0000-0000-000000000049', 'Early microbial keratitis can sometimes present with relatively mild symptoms before progressing rapidly, making a low threshold for urgent referral important in this at-risk population.', 2),
('f7000000-0000-0000-0000-000000000049', 'Prompt specialist assessment, including slit-lamp examination and, if indicated, corneal scraping for microbiological diagnosis, allows timely, targeted treatment to prevent progression and permanent corneal scarring.', 3),
('f7000000-0000-0000-0000-000000000050', 'Branch retinal artery occlusion causes visual field loss corresponding specifically to the retinal territory supplied by the occluded branch vessel, distinguishing it from the complete visual loss of central retinal artery occlusion.', 1),
('f7000000-0000-0000-0000-000000000050', 'The underlying embolic or thrombotic mechanism, and associated vascular risk factors, are shared with central retinal artery occlusion, warranting the same urgent evaluation for an embolic source (e.g. carotid disease, cardiac source) and secondary vascular prevention.', 2),
('f7000000-0000-0000-0000-000000000050', 'Although visual prognosis for the affected field area is often limited once the occlusion is established, identifying and managing the underlying vascular risk factors remains important for preventing further vascular events, including in the fellow eye or cerebral circulation.', 3);
